'use strict';
/* NeuroLocalize 1.9 case bank: plain-language clinical vignettes.
   Each case keeps its original id, region and teaching point. Fields:
   s stem, f findings, q question, o options (o[0] is the best answer; display order is shuffled),
   r reason for each option, fn what each finding tells you, w anatomy, st reasoning steps,
   p pearl, g figures. Synthetic cases for education only; not clinical guidance. */
window.NL_CASES_V2 = {
 'case-01': {ti: 'Right-sided weakness and a numb-feeling hand', k: 'Localize',
  s: 'A 64-year-old right-handed man woke with a weak right arm and leg. His wife says his face looks lopsided. He can understand everything and speaks normally.',
  f: ['Right lower face, arm and leg are weak; he can still wrinkle his forehead', 'Right arm reflexes are brisk and the right big toe goes up when the sole is stroked', 'With his eyes closed he feels pinprick and vibration in the right hand but cannot tell which number you trace on his right palm', 'He identifies numbers traced on his left palm without difficulty'],
  q: 'Where is the lesion?',
  o: ['Left cortex around the central sulcus (motor and sensory strips)', 'Left internal capsule', 'Left side of the pons', 'Right side of the upper spinal cord'],
  r: ['Best fit. The motor strip explains the right face, arm and leg weakness; the sensory strip next to it explains why he cannot read numbers on his palm even though he feels touch.', 'The capsule could cause the same weakness, but it does not take away the higher sensory skill of reading numbers on the palm while basic feeling is intact.', 'A pontine lesion could weaken the right side, but it would not produce a cortical sensory deficit.', 'A spinal cord lesion cannot weaken the face and would not affect palm reading.'],
  fn: ['Lower face plus arm and leg with the forehead spared is a central (upper motor neuron) pattern from the opposite (left) hemisphere.', 'Brisk reflexes and an upgoing toe confirm an upper motor neuron lesion.', 'Feeling touch but failing to read traced numbers (agraphesthesia) is a cortical sensory sign from the opposite parietal cortex.', 'Normal left-hand performance shows he understands the test and that the problem is one-sided.'],
  w: 'The motor and sensory strips lie side by side around the central sulcus. One lesion here weakens the opposite face, arm and leg and disturbs higher sensory processing in the opposite hand.',
  st: ['Brisk reflexes and an upgoing toe put the lesion in the brain or spinal cord.', 'The face is involved, so the lesion is above the spinal cord, in the left hemisphere.', 'Failing to read numbers on the palm with normal basic feeling is a cortical sign, so the cortex is more likely than deep pathways.'],
  p: 'One finding from a second system, here cortical sensation, often localises better than more detail about the weakness.', g: ['cortex', 'umn-lmn']},
 'case-02': {ti: 'Speech that comes out in pieces', k: 'Localize',
  s: 'A 58-year-old woman suddenly could not get her words out at breakfast. She understands her family and gets frustrated with herself.',
  f: ['Her speech is slow and effortful, in short phrases that leave out small words', 'She struggles to name objects and to repeat a sentence', 'She follows spoken commands and points to objects you name', 'Her right lower face and right hand are weak'],
  q: 'Where is the lesion?',
  o: ['Left inferior frontal lobe (Broca area)', 'Left posterior temporal lobe (Wernicke area)', 'Right frontal lobe', 'Left cerebellar hemisphere'],
  r: ['Best fit. Non-fluent speech with good comprehension and poor repetition is Broca aphasia, and the nearby motor strip explains the right face and hand weakness.', 'A posterior temporal lesion gives fluent speech with poor comprehension, the opposite pattern.', 'Language is in the left hemisphere in most people; a right frontal lesion would not cause this aphasia.', 'The cerebellum can slur speech (dysarthria) but does not cause word-finding problems or weakness.'],
  fn: ['Slow, effortful, telegraphic speech is non-fluent aphasia.', 'Poor naming and repetition place the problem in the main language loop.', 'Good comprehension spares the posterior (Wernicke) area.', 'Right face and hand weakness shows the left motor strip next to Broca area is also involved.'],
  w: 'The left inferior frontal gyrus produces speech and sits just in front of the face and hand area of the motor cortex, so Broca aphasia and right face–hand weakness often occur together.',
  st: ['A problem with words, not just articulation, means aphasia.', 'Non-fluent speech with good comprehension points to the front of the language network.', 'Right face and hand weakness confirms the left frontal lobe.'],
  p: 'Test fluency, comprehension and repetition separately; each points to a different part of the language network.', g: ['aphasia-tree', 'cortex']},
 'case-03': {ti: 'Fluent speech that makes no sense', k: 'Localize',
  s: 'A 71-year-old man is brought in because "he talks but nothing he says makes sense." He seems unaware that anything is wrong.',
  f: ['He speaks quickly and easily but uses wrong and made-up words', 'He cannot follow simple spoken or written commands, although his hearing is normal', 'He cannot repeat a short sentence or name a pen', 'His face and limbs move normally'],
  q: 'Where is the lesion?',
  o: ['Left posterior temporal lobe (Wernicke area)', 'Left inferior frontal lobe (Broca area)', 'Left internal capsule', 'Right parietal lobe'],
  r: ['Best fit. Fluent speech full of wrong words, poor comprehension and poor repetition is Wernicke aphasia from the left posterior temporal lobe.', 'Broca area lesions make speech slow and effortful with good comprehension.', 'Deep capsular lesions cause weakness; they rarely cause this kind of aphasia.', 'Right parietal lesions cause neglect, not loss of language comprehension.'],
  fn: ['Fluent speech with wrong or invented words is a fluent aphasia.', 'Poor comprehension with normal hearing is the key Wernicke feature.', 'Poor repetition shows the main language loop is involved.', 'No weakness fits a posterior lesion away from the motor strip.'],
  w: 'The posterior superior temporal gyrus of the dominant hemisphere decodes the meaning of speech. Damage leaves speech flowing but empty of meaning, and people are often unaware of their errors.',
  st: ['Speech flows easily, so this is a fluent aphasia.', 'He cannot understand, which points to the posterior language area.', 'No weakness fits a lesion behind the motor strip.'],
  p: 'Fluent nonsense with unawareness is easy to mistake for confusion; test comprehension directly.', g: ['aphasia-tree', 'cortex']},
 'case-04': {ti: 'Food left on one side of the plate', k: 'Localize',
  s: 'A 68-year-old woman leaves the food on the left of her plate and bumps into door frames on her left. She says nothing is wrong.',
  f: ['She feels a touch on either hand when touched one at a time', 'When both hands are touched together she reports only the right', 'Asked to copy a clock, she draws only the right half', 'Her visual fields are full when tested one side at a time'],
  q: 'Where is the lesion?',
  o: ['Right parietal lobe (attention network)', 'Right occipital lobe', 'Right thalamus', 'Left parietal lobe'],
  r: ['Best fit. Ignoring the left side with extinction and intact basic sensation and vision is left neglect from the right parietal attention network.', 'An occipital lesion causes a real field loss that persists when tested one side at a time.', 'A thalamic lesion would reduce basic sensation on the left.', 'Left parietal lesions rarely cause dense neglect, and when they do it affects the right side.'],
  fn: ['Feeling single touches shows basic sensation is intact.', 'Missing the left touch only when both sides are touched is extinction, an attention sign.', 'Drawing only half a clock is spatial neglect.', 'Full fields to single targets show this is attention, not a blind half-field.'],
  w: 'The right hemisphere attends to both sides of space, the left mainly to the right. A right parietal lesion therefore causes neglect of the left side even when the senses themselves work.',
  st: ['She feels and sees single stimuli, so the senses work.', 'She ignores the left when competing stimuli are present, which is neglect.', 'Left neglect points to the right hemisphere, usually the parietal lobe.'],
  p: 'Always test both sides together; extinction can be the only sign of neglect.', g: ['cortex', 'vascular']},
 'case-05': {ti: 'A quiet man with a weak leg', k: 'Localize',
  s: 'A 66-year-old man has become very quiet over two days. His daughter says he sits still unless prompted and drags his right leg.',
  f: ['His right leg is much weaker than his right arm; his face is normal', 'The right big toe goes up when the sole is stroked', 'He rarely speaks on his own but answers correctly when pushed', 'There is no back pain and no numbness in the foot'],
  q: 'Where is the lesion?',
  o: ['Left medial frontal lobe', 'Left lateral frontal lobe', 'Left internal capsule', 'Lumbar spinal cord'],
  r: ['Best fit. The leg area of the motor strip lies on the inner (medial) surface of the frontal lobe, next to regions that drive motivation; damage gives a weak leg and reduced initiative (abulia).', 'Lateral frontal lesions weaken the face and arm more than the leg.', 'Capsular lesions usually weaken face, arm and leg evenly and do not cause abulia.', 'A lumbar cord lesion would not change his behaviour and would usually affect both legs with sensory signs.'],
  fn: ['Leg weaker than arm points to the medial frontal cortex, where the leg is represented.', 'An upgoing toe confirms an upper motor neuron lesion.', 'Reduced spontaneous speech and activity is abulia, a medial frontal sign.', 'No back pain or foot numbness argues against a spinal or nerve cause.'],
  w: 'The anterior cerebral artery supplies the medial frontal lobe, which contains the leg area of the motor strip and circuits that drive initiation. Damage here gives leg-predominant weakness with apathy.',
  st: ['An upgoing toe makes this a central lesion.', 'Leg much weaker than arm points to the medial surface of the hemisphere.', 'Reduced drive adds a medial frontal sign.'],
  p: 'Leg-predominant weakness with apathy suggests the anterior cerebral artery territory.', g: ['vascular', 'cortex']},
 'case-06': {ti: 'A pure weakness of one side', k: 'Localize',
  s: 'A 61-year-old man with long-standing high blood pressure noticed his left arm and leg became weak over an hour. His speech and understanding are normal.',
  f: ['The left lower face, arm and leg are equally weak', 'Language, attention and visual fields are normal', 'There is no double vision, facial numbness or sensory loss', 'Reflexes on the left are brisk'],
  q: 'Which conclusion does the examination support?',
  o: ['A lesion in the right motor pathway, most likely deep (internal capsule or pons)', 'A lesion in the right motor cortex', 'A lesion in the right side of the spinal cord', 'A lesion of the left brachial plexus'],
  r: ['Best fit. Even face, arm and leg weakness without cortical, sensory or cranial nerve signs is a pure motor stroke, typical of a small deep lesion in the capsule or pons.', 'A cortical lesion large enough to weaken face, arm and leg evenly would usually cause cortical signs.', 'A spinal cord lesion cannot weaken the face.', 'A plexus lesion causes weakness of one limb only, with low reflexes.'],
  fn: ['Even weakness of face, arm and leg suggests fibres packed close together.', 'Normal language, attention and fields remove cortical clues.', 'No cranial or sensory signs make the brainstem tegmentum and thalamus less likely.', 'Brisk reflexes confirm an upper motor neuron lesion.'],
  w: 'Motor fibres for the face, arm and leg converge in the internal capsule and in the ventral pons. A small lesion at either site causes a pure motor hemiparesis.',
  st: ['Brisk reflexes and face involvement place the lesion above the spinal cord on the right.', 'Even weakness without cortical signs suggests a compact deep pathway.', 'The capsule and the pons can give the same picture; imaging decides.'],
  p: 'A pure motor stroke proves the pathway and side, not the exact level.', g: ['compact', 'motor']},
 'case-07': {ti: 'Numb all down one side', k: 'Localize',
  s: 'A 55-year-old woman suddenly felt numb over the whole left side, from her face to her foot. She has no weakness.',
  f: ['Pinprick, temperature and vibration are reduced on the left face, arm, trunk and leg', 'Strength, eye movements and speech are normal', 'She does not neglect the left side and her visual fields are full', 'There is no level on the trunk and the face and body are on the same side'],
  q: 'Where is the lesion?',
  o: ['Right thalamus', 'Right parietal cortex', 'Right side of the pons', 'Left upper spinal cord'],
  r: ['Best fit. All sensations lost over the whole left side, including the face, without weakness is a pure sensory stroke of the right thalamus.', 'Parietal cortex lesions affect higher sensory skills and often cause neglect.', 'A pontine lesion usually gives a crossed pattern (face one side, body the other) or other brainstem signs.', 'A spinal cord lesion cannot affect the face and produces a level on the trunk.'],
  fn: ['Loss of every sensation over the whole left side, including the face, means both sensory systems are affected above the medulla.', 'Normal strength makes a large hemisphere or brainstem lesion unlikely.', 'No neglect argues against the parietal cortex.', 'No level and no crossed pattern exclude the cord and lower brainstem.'],
  w: 'Every ascending sensory pathway, from the face and the body, relays in the ventral posterior thalamus before reaching the cortex. A small thalamic lesion can remove all sensation on the opposite side without weakness.',
  st: ['Face and body on the same side point above the medulla.', 'All modalities lost together suggests a site where the pathways converge.', 'No weakness or cortical signs points to the thalamus.'],
  p: 'Whole-side numbness including the face, with no other signs, is classically thalamic.', g: ['compact', 'sensory-pathways']},
 'case-08': {ti: 'Vertigo, hoarseness and a droopy eyelid', k: 'Localize',
  s: 'A 49-year-old man developed sudden vertigo, vomiting and a hoarse voice after neck manipulation. He keeps falling to the left.',
  f: ['Pinprick is reduced on the left face and on the right arm, trunk and leg', 'His voice is hoarse and the left side of his palate does not lift', 'His left arm is clumsy and his left pupil is small with a slightly droopy lid', 'His face moves normally and hearing is normal'],
  q: 'Where is the lesion?',
  o: ['Left lateral medulla', 'Left medial medulla', 'Left side of the pons', 'Left cerebellar hemisphere only'],
  r: ['Best fit. Crossed pain loss, hoarseness, a Horner syndrome and left limb ataxia all come from structures in the left lateral medulla (Wallenberg syndrome).', 'Medial medullary lesions weaken the tongue and opposite limbs and spare pain sensation and the voice.', 'A pontine lesion usually affects facial movement or hearing, which are normal.', 'The cerebellum explains the clumsiness but not the crossed numbness, hoarseness or Horner syndrome.'],
  fn: ['Face numb on one side and body on the other is a crossed pattern from the lower brainstem.', 'Hoarseness and a weak palate come from the nucleus ambiguus in the lateral medulla.', 'Limb clumsiness (cerebellar peduncle) and a Horner syndrome (sympathetic fibres) are lateral medullary structures.', 'Normal facial movement and hearing place the lesion below the pons.'],
  w: 'The lateral medulla holds the spinal trigeminal nucleus (same-side face pain), the spinothalamic tract (opposite body pain), the nucleus ambiguus, cerebellar connections and descending sympathetic fibres.',
  st: ['A crossed sensory pattern places the lesion in the lower brainstem.', 'Hoarseness and a Horner syndrome are lateral structures.', 'The facial and palatal signs mark the lesion side: left.'],
  p: 'Neck manipulation followed by a crossed sensory pattern should prompt thinking about the vertebral artery and lateral medulla.', g: ['crossed', 'brainstem-rule', 'horner']},
 'case-09': {ti: 'A tongue that pushes to one side', k: 'Localize',
  s: 'A 70-year-old woman has slurred speech and a weak right arm and leg that came on over a morning.',
  f: ['Her tongue pushes to the left when stuck out, and the left side of it is thin', 'The right arm and leg are weak; her face moves normally', 'She cannot feel vibration or tell the position of her right toes', 'Pinprick feels normal everywhere and her palate moves normally'],
  q: 'Where is the lesion?',
  o: ['Left medial medulla', 'Left lateral medulla', 'Left internal capsule', 'Right medial medulla'],
  r: ['Best fit. A left tongue palsy with right limb weakness and right vibration loss is the left medial medulla: the hypoglossal nerve, pyramid and medial lemniscus.', 'Lateral medullary lesions spare the tongue and pyramid and reduce pain sensation instead.', 'A capsular lesion could weaken the right limbs but would weaken the right side of the tongue only mildly and would not waste it.', 'The tongue deviates toward the weak side, so the lesion is on the left.'],
  fn: ['A thin left tongue that pushes to the left is a lower motor neuron left XII palsy.', 'Right limb weakness with a normal face is the left pyramid, below the facial nucleus.', 'Right vibration and position loss is the left medial lemniscus, which has already crossed.', 'Normal pain sensation and palate exclude lateral medullary structures.'],
  w: 'The medial medulla contains the hypoglossal nucleus and fibres, the pyramid and the medial lemniscus, giving the medial medullary (Dejerine) syndrome.',
  st: ['A wasted tongue is a lower motor neuron sign, so the lesion is at the level of XII.', 'Opposite limb weakness and vibration loss are long tracts beside it.', 'The tongue marks the side: left medial medulla.'],
  p: 'The tongue points toward the side of a lower motor neuron XII lesion.', g: ['brainstem-rule', 'cranial']},
 'case-10': {ti: 'A droopy eye and a weak opposite side', k: 'Localize',
  s: 'A 63-year-old man woke with double vision and a drooping left eyelid. His right arm and leg are weak.',
  f: ['The left eyelid droops and the left eye rests down and out', 'The left eye cannot look in or up', 'The right arm and leg are weak with brisk reflexes', 'The left eye can still look out and the face moves normally'],
  q: 'Where is the lesion?',
  o: ['Left midbrain', 'Left cavernous sinus', 'Left pons', 'Right midbrain'],
  r: ['Best fit. A left third nerve palsy with right-sided weakness is the left midbrain, where third nerve fibres pass through the motor pathway (Weber syndrome).', 'The cavernous sinus can cause a third nerve palsy but not weakness of the limbs.', 'The pons carries VI and VII, not III.', 'The third nerve palsy marks the lesion side, which is left.'],
  fn: ['A droopy lid with the eye down and out is a third nerve palsy.', 'Inability to look in or up confirms third nerve muscles are weak.', 'Opposite-side weakness means the motor pathway is involved before it crosses.', 'Normal abduction and face exclude VI and VII and keep the lesion above the pons.'],
  w: 'In the midbrain, third nerve fibres run through the cerebral peduncle, which carries the motor fibres. One lesion causes a same-side third nerve palsy with opposite-side weakness.',
  st: ['A cranial nerve palsy on one side with weakness on the other is a brainstem pattern.', 'The nerve involved, III, sets the level: midbrain.', 'The eye marks the side: left.'],
  p: 'In crossed brainstem syndromes, the cranial nerve gives the level and the side.', g: ['eye-muscles', 'brainstem-rule', 'cranial']},
 'case-11': {ti: 'A face that will not close and opposite weakness', k: 'Localize',
  s: 'A 57-year-old woman has sudden double vision, cannot close her right eye, and her left arm and leg are weak.',
  f: ['The whole right side of her face is weak, including the forehead', 'The right eye cannot look out to the right', 'Her left arm and leg are weak with brisk reflexes', 'Tongue movement and up–down eye movements are normal'],
  q: 'Where is the lesion?',
  o: ['Right lower pons', 'Right internal capsule', 'Right lateral medulla', 'Right facial nerve outside the brainstem'],
  r: ['Best fit. Right VI and VII palsies with left-sided weakness come from the right lower pons, where those nerves pass near the motor pathway.', 'A capsular lesion would weaken the opposite lower face only and would not affect eye abduction.', 'The lateral medulla contains neither VI nor VII and does not cause weakness of the limbs.', 'A facial nerve lesion would not cause eye or limb weakness.'],
  fn: ['Whole-face weakness including the forehead is a nuclear or nerve-level facial palsy.', 'A right eye that cannot abduct is a right sixth nerve problem.', 'Opposite limb weakness means the motor pathway beside them.', 'Normal tongue and vertical gaze keep the lesion in the pons.'],
  w: 'In the lower pons, the facial nerve fibres loop around the abducens nucleus, and both lie close to the descending motor tract. One lesion gives same-side VI and VII palsies with opposite-side weakness.',
  st: ['Cranial nerve signs on one side with weakness on the other mean the brainstem.', 'VI and VII together set the level: lower pons.', 'The face and eye mark the side: right.'],
  p: 'VI and VII travel together in the lower pons; when both fail with opposite weakness, think of the pons.', g: ['gaze-circuit', 'facial', 'brainstem-rule']},
 'case-12': {ti: 'Double vision looking to the side', k: 'Localize',
  s: 'A 29-year-old woman with previous episodes of numbness has new double vision when she looks to the right.',
  f: ['When she looks right, her left eye moves inward slowly and not fully', 'At the same time her right eye flickers as it moves out', 'Both eyes turn inward normally when she looks at her nose', 'Her eyelids, pupils and outward movement of each eye are normal'],
  q: 'Where is the lesion?',
  o: ['Left medial longitudinal fasciculus (MLF)', 'Left third nerve', 'Right sixth nerve nucleus', 'Right medial longitudinal fasciculus'],
  r: ['Best fit. The left eye fails to move in on right gaze but converges normally, which is a left internuclear ophthalmoplegia from the left MLF.', 'A third nerve palsy would also stop convergence and affect the lid or vertical movement.', 'A sixth nucleus lesion stops both eyes looking right.', 'The MLF lesion is on the side of the eye that fails to move in: left.'],
  fn: ['Slow inward movement of the left eye on right gaze is the key sign of a left internuclear ophthalmoplegia.', 'Flickering of the right eye as it moves out is the usual companion sign.', 'Normal convergence shows the left medial rectus and its nerve work.', 'Normal lids, pupils and abduction exclude third and sixth nerve palsies.'],
  w: 'To look right, the right sixth nucleus sends a signal up the left MLF to the left medial rectus. A left MLF lesion breaks this link, so the left eye lags, while convergence, which uses another route, is spared.',
  st: ['One eye fails to adduct only on side gaze.', 'Convergence is normal, so the muscle and nerve work.', 'The faulty link is the MLF on the side of the lagging eye.'],
  p: 'In a young adult with relapsing symptoms, an internuclear ophthalmoplegia suggests demyelination.', g: ['gaze-circuit', 'eye-muscles']},
 'case-13': {ti: 'A drooping lid and a large pupil', k: 'Localize',
  s: 'A 52-year-old woman has a severe headache and her right eyelid has dropped over a day. She sees double when she lifts the lid.',
  f: ['The right lid droops and the right eye rests down and out', 'The right eye cannot look in, up or down', 'The right pupil is large and reacts poorly; the eye can still look out', 'There is no weakness, numbness or other cranial nerve problem'],
  q: 'Where is the lesion?',
  o: ['Right third (oculomotor) nerve', 'Right fourth (trochlear) nerve', 'Right sixth (abducens) nerve', 'Right medial longitudinal fasciculus'],
  r: ['Best fit. Ptosis, an eye that rests down and out, loss of inward, upward and downward movement and a large pupil are a complete right third nerve palsy.', 'A fourth nerve palsy causes only vertical double vision and no ptosis.', 'A sixth nerve palsy stops outward movement, which is preserved.', 'An MLF lesion affects inward movement only on side gaze and causes no ptosis or pupil change.'],
  fn: ['A droopy lid with the eye down and out is the third nerve pattern.', 'Loss of inward, upward and downward movement confirms third nerve muscles.', 'A large pupil shows the third nerve\'s parasympathetic fibres are affected; preserved abduction spares VI.', 'No other signs suggest the nerve outside the brainstem.'],
  w: 'The third nerve supplies the lid elevator, the pupil constrictor and all eye muscles except the lateral rectus and superior oblique. A pupil-involving palsy with headache raises concern for compression, such as an aneurysm.',
  st: ['Ptosis plus an eye down and out is a third nerve palsy.', 'The pupil is involved, which suggests compression of the nerve.', 'No long-tract signs place it outside the brainstem.'],
  p: 'A painful third nerve palsy with a large pupil needs urgent assessment for an aneurysm.', g: ['eye-muscles', 'pupil-reflex', 'cavernous-sinus']},
 'case-14': {ti: 'Double vision looking left', k: 'Localize',
  s: 'A 45-year-old man with diabetes has double vision side by side, worst when he looks to the left.',
  f: ['His left eye cannot move fully out to the left', 'His right eye moves fully inward when he looks left', 'Up–down movements and convergence are normal', 'There is no ptosis and his face moves normally'],
  q: 'Where is the lesion?',
  o: ['Left sixth (abducens) nerve', 'Left sixth nerve nucleus in the pons', 'Right medial longitudinal fasciculus', 'Left third nerve'],
  r: ['Best fit. Only the left eye fails to move out, while the right eye moves in normally: a left sixth nerve palsy.', 'A nucleus lesion causes a gaze palsy: the right eye would also fail to move in when looking left.', 'A right MLF lesion affects inward movement of the right eye, which is normal.', 'A third nerve lesion would affect inward and vertical movements and the lid.'],
  fn: ['A left eye that cannot abduct points to the left lateral rectus pathway.', 'Normal right eye adduction shows there is no gaze palsy.', 'Normal vertical movement and convergence spare III and IV.', 'No facial weakness argues against a pontine nuclear lesion, which often involves VII.'],
  w: 'The sixth nucleus drives both the same-side lateral rectus and, through the MLF, the opposite medial rectus. When only one eye fails to move out, the problem is the nerve rather than the nucleus.',
  st: ['Horizontal double vision worst looking left points to a muscle that moves an eye left.', 'Only the left eye fails to abduct, so it is the left lateral rectus pathway.', 'The other eye adducts normally, so it is the nerve, not the nucleus.'],
  p: 'In diabetes, an isolated sixth nerve palsy is often microvascular, but persistent or progressive palsies need investigation.', g: ['eye-muscles', 'gaze-circuit']},
 'case-15': {ti: 'Half the face suddenly weak', k: 'Localize',
  s: 'A 34-year-old woman noticed in the mirror that the left side of her face had dropped overnight. She has an ache behind her left ear.',
  f: ['She cannot wrinkle her left forehead, close her left eye fully or smile on the left', 'There is no droopy lid, double vision or weakness that changes with use', 'Facial feeling and jaw strength are normal', 'Arms and legs are normal'],
  q: 'Where is the lesion?',
  o: ['Left facial nerve (peripheral)', 'Right motor cortex', 'Left trigeminal nerve', 'Neuromuscular junction'],
  r: ['Best fit. Weakness of the whole left face including the forehead, with nothing else, is a peripheral left facial nerve palsy, such as Bell palsy.', 'A cortical lesion would spare the forehead and usually weaken the hand too.', 'The trigeminal nerve gives facial feeling and moves the jaw, which are normal.', 'Junction disorders fluctuate and usually affect the eyelids and eye movements on both sides.'],
  fn: ['Forehead, eye closure and smile all weak on one side is a peripheral facial pattern.', 'No ptosis, double vision or fatigue argues against a junction disorder.', 'Normal facial feeling and jaw strength spare the trigeminal nerve.', 'Normal limbs exclude a central lesion.'],
  w: 'Upper-face motor neurons receive input from both hemispheres, so central lesions spare the forehead. Forehead weakness means the facial nucleus or nerve on the same side.',
  st: ['Check the forehead: it is weak.', 'So the lesion is in the facial nucleus or nerve on the same side.', 'No other cranial or limb signs point to the nerve outside the brainstem.'],
  p: 'Forehead weakness separates a peripheral facial palsy from a stroke.', g: ['facial', 'cranial']},
 'case-16': {ti: 'One leg weak, the other numb', k: 'Localize',
  s: 'A 31-year-old man was stabbed in the back. He cannot move his left leg properly and says his right leg cannot feel the bath water.',
  f: ['The left leg is weak with brisk reflexes below a level on the chest', 'He cannot feel vibration or toe position in the left leg', 'He cannot feel pinprick or temperature in the right leg, starting just below the same level', 'His arms and face are normal'],
  q: 'Where is the lesion?',
  o: ['Left half of the thoracic spinal cord', 'Right half of the thoracic spinal cord', 'Back of the thoracic cord (dorsal columns)', 'Left side of the brain'],
  r: ['Best fit. Same-side weakness and vibration loss with opposite-side pain loss below a level is a left hemicord (Brown-Séquard) lesion.', 'The weakness and vibration loss mark the lesion side, which is left.', 'A dorsal column lesion would not cause weakness or pain loss.', 'A brain lesion would affect the arm or face and would not cause a level on the chest.'],
  fn: ['Left leg weakness below a level is the left corticospinal tract in the cord, which has already crossed.', 'Left vibration loss is the left dorsal column, which has not yet crossed.', 'Right pain loss is the left spinothalamic tract carrying fibres that crossed from the right.', 'Normal arms place the lesion in the thoracic cord.'],
  w: 'At one level of the cord, motor and vibration fibres serve the same side, while pain fibres serve the opposite side. One-sided damage splits the modalities.',
  st: ['A level on the chest points to the spinal cord.', 'Weakness and vibration loss on one side, pain loss on the other, is a hemicord pattern.', 'The weak side is the lesion side: left.'],
  p: 'In a hemicord lesion, the weak leg feels pain; the strong leg does not.', g: ['hemicord', 'cord-syndromes', 'sensory-pathways']},
 'case-17': {ti: 'Paralysed legs that still feel vibration', k: 'Localize',
  s: 'A 67-year-old man had chest and back pain during surgery on his aorta. Afterwards he cannot move his legs.',
  f: ['Both legs are weak and later become stiff with brisk reflexes', 'He cannot feel pinprick or temperature below the middle of his chest', 'He can still feel a tuning fork and knows the position of his toes', 'His arms and face are normal'],
  q: 'Where is the lesion?',
  o: ['Front of the thoracic spinal cord (anterior cord)', 'Back of the thoracic spinal cord (posterior cord)', 'Both lumbar plexuses', 'Both sides of the brain'],
  r: ['Best fit. Loss of strength and pain sensation with preserved vibration and position below a level is the anterior cord syndrome, often from spinal artery ischaemia.', 'A posterior cord lesion would remove vibration and position, which are preserved.', 'Plexus lesions do not cause a chest level or brisk reflexes.', 'A brain lesion would not cause a sensory level and would usually affect the arms.'],
  fn: ['Both legs weak with later upper motor neuron signs means both corticospinal tracts.', 'Pain and temperature loss below a level means both spinothalamic tracts.', 'Preserved vibration and position spare the dorsal columns at the back.', 'Normal arms place the lesion in the thoracic cord.'],
  w: 'The anterior spinal artery supplies the front two-thirds of the cord, including the motor and pain pathways. The dorsal columns, supplied separately, are spared.',
  st: ['A sensory level points to the cord.', 'Strength and pain are lost but vibration is spared.', 'That pattern fits damage to the front of the cord.'],
  p: 'Aortic surgery with paraplegia but preserved vibration suggests anterior spinal artery infarction.', g: ['cord-syndromes', 'sensory-pathways']},
 'case-18': {ti: 'Burns on the shoulders he did not feel', k: 'Localize',
  s: 'A 33-year-old man has painless burns on both forearms from cooking. His shoulders and arms do not feel hot or cold.',
  f: ['He cannot feel pinprick or temperature over both shoulders and arms', 'Sensation is normal on his chest below this and on his neck above it', 'He feels vibration and knows the position of his fingers normally', 'His face feels normal'],
  q: 'Where is the lesion?',
  o: ['Centre of the cervical spinal cord', 'Back of the cervical cord (dorsal columns)', 'Several cervical nerve roots on both sides', 'Both sides of the brain'],
  r: ['Best fit. A cape of pain and temperature loss over both shoulders with vibration spared is the central cord pattern, as from a syrinx.', 'Dorsal column lesions remove vibration and position, which are normal.', 'Root lesions affect all sensations in their bands, including vibration.', 'A brain lesion would not cause a cape on both sides with normal sensation below.'],
  fn: ['Pain and temperature loss over both shoulders and arms is a cape-shaped band.', 'Normal sensation above and below shows only a few cord segments are affected.', 'Preserved vibration and position spare the dorsal columns.', 'Normal facial feeling keeps the lesion below the brainstem.'],
  w: 'Pain and temperature fibres cross just in front of the central canal soon after entering the cord. A lesion expanding from the centre cuts these crossing fibres on both sides at those levels only.',
  st: ['Painless burns suggest lost pain and temperature sense.', 'A band on both sides with normal sensation below means a few segments in the middle of the cord.', 'Spared vibration confirms a central lesion.'],
  p: 'Painless burns on the hands and a cape of sensory loss suggest a syrinx.', g: ['cord-syndromes', 'sensory-pathways', 'dermatome-landmarks']},
 'case-19': {ti: 'Unsteady in the dark', k: 'Localize',
  s: 'A 58-year-old vegan woman has become unsteady over months, especially in the dark or when washing her face in the shower.',
  f: ['She cannot feel vibration or toe position below the middle of her chest', 'Pinprick sensation and strength are normal', 'Her knee and ankle reflexes are present', 'She sways and nearly falls when she stands with her feet together and eyes closed'],
  q: 'Where is the lesion?',
  o: ['Back of the thoracic spinal cord (dorsal columns)', 'Cerebellum', 'Nerves in the feet (length-dependent neuropathy)', 'Inner ears on both sides'],
  r: ['Best fit. Loss of vibration and position below a chest level with a positive Romberg test points to the dorsal columns, as in vitamin B12 deficiency.', 'Cerebellar unsteadiness changes little when the eyes close and does not cause sensory loss.', 'A neuropathy starts in the feet without a chest level and usually loses the ankle reflexes.', 'Inner ear loss causes imbalance in the dark but not sensory loss.'],
  fn: ['Vibration and position loss below a chest level points to the dorsal columns.', 'Normal pin sensation and strength spare the other cord tracts.', 'Present reflexes argue against a neuropathy.', 'Falling with eyes closed is a positive Romberg sign: sensory ataxia.'],
  w: 'The dorsal columns carry position sense up the back of the cord. When they fail, balance depends on vision, so it worsens in the dark.',
  st: ['Unsteadiness worse in the dark suggests lost position sense.', 'A chest level shows the problem is in the cord.', 'Only vibration and position are lost, so it is the dorsal columns.'],
  p: 'A strict vegan diet with sensory ataxia should prompt a check of vitamin B12.', g: ['sensory-pathways', 'cord-syndromes', 'coordination']},
 'case-20': {ti: 'Clumsy hands and stiff legs', k: 'Localize',
  s: 'A 69-year-old retired builder has dropped things for six months and now walks stiffly. He has neck stiffness.',
  f: ['The small muscles of both hands are thin and weak', 'His legs are stiff with brisk reflexes and upgoing toes', 'He has reduced pinprick in the hands and below the collarbones', 'His face, speech and swallowing are normal'],
  q: 'Where is the lesion?',
  o: ['Lower cervical spinal cord', 'Thoracic spinal cord', 'Nerve roots in the neck only', 'Motor neuron disease (both motor systems)'],
  r: ['Best fit. Lower motor neuron signs in the hands, upper motor neuron signs in the legs and a sensory level below the collarbones point to the lower cervical cord, as in cervical myelopathy.', 'A thoracic lesion would spare the hands.', 'Root lesions explain the hands but not the stiff legs or the sensory level.', 'Motor neuron disease does not cause sensory loss.'],
  fn: ['Thin, weak hand muscles are lower motor neuron signs at the C8–T1 segments.', 'Brisk leg reflexes and upgoing toes are upper motor neuron signs below.', 'A sensory level below the collarbones confirms a cord lesion.', 'Normal face and swallowing keep the lesion below the brainstem.'],
  w: 'A cervical cord lesion damages the motor neurons for the hands at its own level and the descending motor tracts to the legs that pass through it.',
  st: ['Hand wasting is a lower motor neuron sign; stiff legs are upper motor neuron signs.', 'A sensory level confirms the cord.', 'The hands set the level: lower cervical.'],
  p: 'Wasted hands with brisk legs suggests a cervical cord lesion; check for a sensory level.', g: ['umn-lmn', 'cord-syndromes', 'root-signatures']},
 'case-21': {ti: 'Back pain, weak legs and trouble passing urine', k: 'Localize',
  s: 'A 44-year-old warehouse worker has severe back pain shooting down both legs and, since this morning, has not been able to pass urine properly.',
  f: ['Both legs are weak in an uneven pattern below the knees', 'Ankle reflexes are absent and the toes go down', 'He is numb around the buttocks and back passage', 'Sensation on his trunk is normal'],
  q: 'Where is the lesion?',
  o: ['Cauda equina (lumbar and sacral nerve roots)', 'Thoracic spinal cord', 'Both sciatic nerves', 'Both lumbar plexuses'],
  r: ['Best fit. Root pain in both legs, uneven lower motor neuron weakness, saddle numbness and urinary retention point to the cauda equina, needing urgent assessment.', 'A thoracic cord lesion causes stiff legs, brisk reflexes and a trunk level.', 'Sciatic nerve lesions do not cause saddle numbness or bladder problems.', 'Plexus lesions are usually one-sided and do not cause saddle or bladder symptoms.'],
  fn: ['Uneven weakness in both legs suggests many roots at once.', 'Absent reflexes and downgoing toes are lower motor neuron signs.', 'Saddle numbness points to the sacral roots.', 'No trunk level rules out a thoracic cord lesion.'],
  w: 'Below the end of the cord, the lumbar and sacral roots run together as the cauda equina. Compression causes root pain, weakness, saddle numbness and bladder failure.',
  st: ['Weakness with low reflexes means lower motor neurons.', 'Both legs and the saddle are involved.', 'That fits many roots together in the cauda equina.'],
  p: 'Back pain with saddle numbness or urinary retention is an emergency.', g: ['conus-cauda', 'lumbosacral']},
 'case-22': {ti: 'Neck pain into the middle finger', k: 'Localize',
  s: 'A 47-year-old painter has had neck pain shooting down his right arm into the middle finger for three weeks. Turning his head to the right makes it worse.',
  f: ['His right triceps and wrist flexors are weak', 'The right triceps reflex is reduced; the biceps reflex is normal', 'The middle finger is numb', 'Strength in the shoulder and hand muscles is normal'],
  q: 'Where is the lesion?',
  o: ['Right C7 nerve root', 'Right radial nerve', 'Right C5 nerve root', 'Right ulnar nerve'],
  r: ['Best fit. Weak triceps and wrist flexors (two different nerves), a reduced triceps reflex and middle finger numbness with neck pain point to the C7 root.', 'The radial nerve does not supply the wrist flexors or the middle finger skin on the palm side, and neck movement would not worsen it.', 'C5 affects the shoulder and biceps reflex.', 'The ulnar nerve supplies the little finger and hand muscles.'],
  fn: ['Weak triceps (radial nerve) and wrist flexors (median nerve) share C7.', 'A reduced triceps reflex with a normal biceps reflex points to C7.', 'Middle finger numbness follows the C7 dermatome.', 'Normal shoulder and hand muscles spare C5 and C8.'],
  w: 'A root supplies muscles through several nerves. When muscles from two different nerves share one root and are weak together, the root is more likely than either nerve.',
  st: ['Neck pain worse with movement suggests a root.', 'The weak muscles use two nerves but share C7.', 'The reflex and finger confirm C7.'],
  p: 'Test muscles that share a root but use different nerves.', g: ['root-signatures', 'dermatome-landmarks', 'reflex-arc']},
 'case-23': {ti: 'Foot drop after back pain', k: 'Localize',
  s: 'A 52-year-old woman lifted a heavy box and developed back pain shooting down her right leg. Now her right foot slaps when she walks.',
  f: ['Lifting her right foot and big toe is weak', 'Turning the foot inward and moving the leg out to the side are also weak', 'She is numb on the top of the foot', 'The ankle reflex is normal'],
  q: 'Where is the lesion?',
  o: ['Right L5 nerve root', 'Right common fibular nerve', 'Right S1 nerve root', 'Right femoral nerve'],
  r: ['Best fit. Foot drop plus weak inward turning and hip abduction (muscles of three different nerves that share L5) with back pain points to the L5 root.', 'The common fibular nerve does not supply inward turning or hip abduction.', 'S1 weakens pushing off and reduces the ankle reflex.', 'The femoral nerve straightens the knee.'],
  fn: ['Weak foot and toe lifting occurs with both L5 and fibular lesions.', 'Weak inward turning (tibial nerve) and hip abduction (gluteal nerve) share L5 but not the fibular nerve.', 'Numbness on the top of the foot fits L5 or the fibular nerve.', 'A normal ankle reflex makes S1 unlikely.'],
  w: 'L5 reaches the leg through the fibular, tibial and superior gluteal nerves. Weakness in all three territories points to the root.',
  st: ['Foot drop can be the L5 root or the fibular nerve.', 'Inward turning and hip abduction are weak too.', 'Those muscles use other nerves but share L5.'],
  p: 'In every foot drop, test inward turning and hip abduction.', g: ['lumbosacral', 'root-signatures']},
 'case-24': {ti: 'Cannot stand on tiptoe', k: 'Localize',
  s: 'A 41-year-old man has back pain running down the back of his right leg to the outer foot. He cannot stand on his right tiptoes.',
  f: ['Pushing the right foot down and turning it outward are weak', 'The right ankle reflex is reduced; the knee reflex is normal', 'The outer edge of the foot and sole are numb', 'Lifting the foot and big toe is normal'],
  q: 'Where is the lesion?',
  o: ['Right S1 nerve root', 'Right tibial nerve', 'Right L5 nerve root', 'Right L4 nerve root'],
  r: ['Best fit. Weak plantar flexion and eversion, a reduced ankle reflex and outer foot numbness with back pain point to the S1 root.', 'The tibial nerve does not turn the foot outward.', 'L5 affects foot lifting, which is normal.', 'L4 affects knee extension and the knee reflex, which are normal.'],
  fn: ['Weak pushing down (tibial) and turning out (fibular) share S1.', 'A reduced ankle reflex is the S1 reflex.', 'Outer foot and sole numbness follows the S1 dermatome.', 'Normal foot lifting spares L5.'],
  w: 'S1 supplies the calf, the foot evertors and gluteus maximus and carries the ankle reflex. Back pain radiating down the back of the leg is typical.',
  st: ['Back pain down the leg suggests a root.', 'The weak muscles use two nerves but share S1.', 'The ankle reflex and outer foot confirm S1.'],
  p: 'Standing on tiptoe is a quick bedside test of S1.', g: ['root-signatures', 'lumbosacral', 'reflex-arc']},
 'case-25': {ti: 'Foot drop after crossing the legs', k: 'Localize',
  s: 'A 38-year-old woman lost a lot of weight quickly and often sits with her legs crossed. She now trips because her left foot will not lift.',
  f: ['Lifting the left foot and turning it outward are weak', 'Turning the foot inward, pushing it down and moving the leg out to the side are normal', 'The top of the foot is numb; the sole feels normal', 'There is no back pain'],
  q: 'Where is the lesion?',
  o: ['Left common fibular nerve at the knee', 'Left L5 nerve root', 'Left sciatic nerve', 'Left tibial nerve'],
  r: ['Best fit. Weak foot lifting and eversion with normal inward turning and hip abduction, numbness on the top of the foot and leg crossing point to the common fibular nerve at the fibular head.', 'L5 would also weaken inward turning and hip abduction.', 'A sciatic lesion would usually weaken tibial-supplied muscles too.', 'The tibial nerve pushes the foot down and supplies the sole.'],
  fn: ['Weak lifting and turning out are the deep and superficial fibular branches.', 'Normal inward turning and hip abduction exclude L5.', 'Top-of-foot numbness with a normal sole fits the fibular nerve.', 'No back pain makes a root less likely.'],
  w: 'The common fibular nerve winds around the fibular neck just below the knee, where pressure from leg crossing, especially after weight loss, can damage it.',
  st: ['Foot drop can be the fibular nerve or L5.', 'Inward turning and hip abduction are normal.', 'So the lesion is the fibular nerve.'],
  p: 'Weight loss and leg crossing are classic causes of fibular nerve palsy.', g: ['lumbosacral', 'dermatome-landmarks']},
 'case-26': {ti: 'Tingling fingers at night', k: 'Localize',
  s: 'A 50-year-old woman wakes at night with tingling in her right thumb, index and middle fingers. Shaking her hand helps.',
  f: ['The thumb, index and middle fingers are numb on the palm side', 'Lifting the thumb away from the palm is weak; spreading the fingers is normal', 'The skin over the base of the thumb (palm) feels normal', 'Bending the thumb tip and turning the forearm over are strong'],
  q: 'Where is the lesion?',
  o: ['Median nerve at the wrist (carpal tunnel)', 'Median nerve in the forearm', 'C6 nerve root', 'Ulnar nerve at the elbow'],
  r: ['Best fit. Night-time tingling in the median fingers, weak thumb abduction and normal palm and forearm muscles point to carpal tunnel syndrome.', 'A forearm lesion would weaken thumb-tip bending and forearm turning, and numb the base of the thumb.', 'C6 would cause neck pain and affect the biceps or wrist extensors.', 'The ulnar nerve supplies the little finger and finger spreading.'],
  fn: ['Numbness of thumb, index and middle fingers is the median nerve territory.', 'Weak thumb abduction with normal finger spreading isolates median hand muscles.', 'Normal skin at the base of the thumb spares a branch that leaves before the wrist.', 'Strong forearm muscles spare the median nerve above the wrist.'],
  w: 'The median nerve passes through the carpal tunnel at the wrist. A branch to the skin of the palm leaves before the tunnel, so the palm feels normal in carpal tunnel syndrome.',
  st: ['The numb fingers are the median nerve territory.', 'Forearm muscles and palm skin are normal.', 'So the lesion is at the wrist.'],
  p: 'Normal sensation over the base of the thumb supports carpal tunnel syndrome.', g: ['hand-nerves']},
 'case-27': {ti: 'Little finger tingling on the phone', k: 'Localize',
  s: 'A 36-year-old call-centre worker gets tingling in her right ring and little fingers when she holds the phone with her elbow bent.',
  f: ['Spreading the fingers is weak and the little finger is numb', 'The back of the hand on the little-finger side is numb too', 'Thumb abduction is strong and the inner forearm feels normal', 'Tapping behind the elbow sends tingling into the little finger'],
  q: 'Where is the lesion?',
  o: ['Ulnar nerve at the elbow', 'Ulnar nerve at the wrist', 'C8 nerve root', 'Median nerve at the wrist'],
  r: ['Best fit. Ulnar weakness and numbness including the back of the hand, worse with elbow bending and with a tingling tap behind the elbow, point to the ulnar nerve at the elbow.', 'A wrist lesion spares the back of the hand, because that branch leaves above the wrist.', 'C8 would weaken thumb abduction and numb the inner forearm.', 'The median nerve supplies the thumb side of the hand.'],
  fn: ['Weak finger spreading and a numb little finger are the ulnar nerve.', 'A numb back of the hand means the lesion is above the wrist.', 'Strong thumb abduction and a normal inner forearm exclude C8.', 'Tingling on tapping the elbow suggests the site.'],
  w: 'The branch supplying the back of the hand leaves the ulnar nerve above the wrist, so its involvement places the lesion higher, and elbow bending stretches the nerve in the cubital tunnel.',
  st: ['Little finger numbness and weak spreading are ulnar.', 'The back of the hand is numb, so it is above the wrist.', 'Elbow triggers and a positive tap point to the elbow.'],
  p: 'Check the back of the hand to tell an elbow from a wrist ulnar lesion.', g: ['hand-nerves', 'brachial-plexus']},
 'case-28': {ti: 'Wrist drop after a night out', k: 'Localize',
  s: 'A 27-year-old man fell asleep drunk with his arm over the back of a chair. In the morning he could not lift his right wrist.',
  f: ['He cannot lift his wrist or straighten his fingers', 'The back of the hand between the thumb and index finger is numb', 'Straightening the elbow (triceps) and lifting the shoulder are strong', 'Bending the wrist and turning the palm down are normal'],
  q: 'Where is the lesion?',
  o: ['Radial nerve at the upper arm', 'Posterior cord of the brachial plexus', 'C7 nerve root', 'Posterior interosseous nerve in the forearm'],
  r: ['Best fit. Wrist drop with numbness on the back of the first web space and a strong triceps points to the radial nerve compressed in the upper arm ("Saturday night palsy").', 'A posterior cord lesion would also weaken the shoulder and triceps.', 'C7 would weaken the triceps and wrist flexors.', 'The posterior interosseous nerve does not carry sensation and spares one wrist extensor, so the wrist can still lift with tilt.'],
  fn: ['Wrist and finger drop is a radial nerve pattern.', 'Numbness of the first web space on the back of the hand is the radial sensory branch.', 'A strong triceps places the lesion below the triceps branches.', 'Normal wrist flexion and pronation spare the median nerve and C7.'],
  w: 'The radial nerve spirals around the back of the humerus after supplying the triceps. Pressure here causes wrist drop and hand numbness while sparing the triceps.',
  st: ['Wrist drop with web-space numbness is radial.', 'The triceps works, so the lesion is below its branches.', 'That is the radial nerve at the upper arm.'],
  p: 'A strong triceps in wrist drop places the lesion around the middle of the humerus.', g: ['hand-nerves', 'brachial-plexus']},
 'case-29': {ti: 'A motorbike fall onto the shoulder', k: 'Localize',
  s: 'A 22-year-old motorcyclist landed on his shoulder, forcing his head away from it. His arm now hangs by his side, turned inward.',
  f: ['He cannot lift his arm out to the side, turn it outward or bend his elbow strongly', 'The outer side of his upper arm and forearm is numb', 'His shoulder blade does not wing and he can pull it back normally', 'His hand and wrist work normally'],
  q: 'Where is the lesion?',
  o: ['Upper trunk of the brachial plexus', 'Axillary nerve', 'Musculocutaneous nerve', 'C8 and T1 nerve roots'],
  r: ['Best fit. Shoulder abduction, external rotation and elbow flexion (three nerves, all C5–C6) after the neck was stretched away from the shoulder point to the upper trunk (Erb palsy pattern).', 'The axillary nerve does not bend the elbow.', 'The musculocutaneous nerve does not lift the shoulder.', 'C8–T1 affect the hand, which is normal.'],
  fn: ['Weak shoulder abduction, external rotation and elbow flexion span several nerves that share C5–C6.', 'Numbness of the outer arm and forearm fits C5–C6.', 'No winging and normal scapular retraction spare nerves that leave right at the roots, so the lesion is beyond them.', 'A normal hand spares the lower plexus.'],
  w: 'The upper trunk is formed by C5 and C6. Forcing the head away from the shoulder stretches it, weakening the shoulder and elbow and leaving the arm hanging turned inward ("waiter\'s tip").',
  st: ['Several nerves are weak, all from C5–C6.', 'Nerves that leave right at the roots are spared.', 'So the lesion is the upper trunk of the plexus.'],
  p: 'Scapular winging or weak rhomboids would suggest the roots rather than the trunk.', g: ['brachial-plexus']},
 'case-30': {ti: 'Weak hand and numb inner forearm', k: 'Localize',
  s: 'A 62-year-old smoker has had a deep ache in his left shoulder for weeks and now his left hand is weak.',
  f: ['Thumb abduction, finger spreading and finger straightening are all weak', 'The inner forearm and little-finger side of the hand are numb', 'His left pupil is small and the lid droops slightly', 'Shoulder and elbow strength are normal'],
  q: 'Where is the lesion?',
  o: ['Lower trunk of the brachial plexus (lung apex)', 'Ulnar nerve at the elbow', 'Median nerve at the wrist', 'Left cervical spinal cord'],
  r: ['Best fit. Weakness in median, ulnar and radial hand muscles (all C8–T1), inner forearm numbness, shoulder pain and a Horner syndrome in a smoker point to the lower plexus at the lung apex (Pancoast tumour).', 'An ulnar lesion spares median and radial muscles and the inner forearm.', 'A median lesion spares the ulnar and radial muscles.', 'A cord lesion would cause leg signs.'],
  fn: ['Weak muscles from three nerves share C8–T1.', 'Inner forearm numbness is C8–T1 territory beyond the ulnar nerve.', 'A Horner syndrome shows the sympathetic chain at the lung apex is involved.', 'Normal shoulder and elbow spare the upper plexus.'],
  w: 'The lower trunk (C8–T1) runs over the lung apex next to the sympathetic chain. A tumour here causes shoulder pain, hand weakness and a Horner syndrome.',
  st: ['Hand weakness crosses three nerves, so it is not one nerve.', 'All share C8–T1 and the inner forearm is numb.', 'A Horner syndrome points to the lung apex.'],
  p: 'Shoulder pain, hand weakness and a Horner syndrome in a smoker need a chest image.', g: ['brachial-plexus', 'horner', 'hand-nerves']}
};
Object.assign(window.NL_CASES_V2, {
 'case-31': {ti: 'Numb feet climbing to the ankles', k: 'Localize',
  s: 'A 63-year-old man with diabetes for 15 years says his feet feel like he is walking on cotton wool. It started in the toes and has crept up to his ankles.',
  f: ['Pinprick and vibration are reduced in both feet, worst at the toes and improving toward the knees', 'Both ankle reflexes are absent; knee and arm reflexes are normal', 'His hands are only slightly affected and there is no level on the trunk', 'Strength is normal apart from mild weakness of toe extension'],
  q: 'Where is the problem?',
  o: ['Peripheral nerves (length-dependent polyneuropathy)', 'Back of the spinal cord (dorsal columns)', 'Lumbar and sacral nerve roots', 'Both cerebral hemispheres'],
  r: ['Best fit. Symmetric loss that starts in the toes and rises, with absent ankle reflexes, is a length-dependent polyneuropathy, common in diabetes.', 'A dorsal column lesion gives a trunk level and spares the ankle reflexes.', 'Root lesions follow bands on the leg and are usually painful and uneven.', 'Brain lesions do not cause symmetric stocking loss.'],
  fn: ['Symmetric loss worst at the toes and fading upward is a stocking gradient.', 'Lost ankle reflexes with normal knees follow the same length gradient.', 'Hands less affected and no trunk level argue against a cord lesion.', 'Mild distal weakness fits the longest motor nerves being affected too.'],
  w: 'In a length-dependent polyneuropathy the longest nerve fibres, to the feet, fail first, so symptoms start in the toes, rise up the legs and later reach the fingers.',
  st: ['Both sides, symmetric and starting at the toes.', 'The longest nerves fail first, and ankle reflexes go early.', 'That is a length-dependent polyneuropathy.'],
  p: 'Numbness that reaches the knees before it reaches the fingertips is length-dependent.', g: ['body-patterns', 'reflex-arc']},
 'case-32': {ti: 'Double vision by the evening', k: 'Localize',
  s: 'A 34-year-old teacher has drooping eyelids and double vision that get worse through the day. By the end of a lesson her voice becomes nasal.',
  f: ['Her eyelids droop more after looking up for a minute and recover after rest', 'Counting aloud to 50 makes her voice softer and nasal', 'Pupils, sensation and reflexes are normal', 'There is no fixed weakness on one side'],
  q: 'Where is the problem?',
  o: ['Neuromuscular junction (myasthenia pattern)', 'Brainstem', 'Third nerves on both sides', 'Muscle (myopathy)'],
  r: ['Best fit. Weakness of eyelids, eyes and voice that worsens with use and recovers with rest, with normal pupils, sensation and reflexes, is myasthenia gravis.', 'A brainstem lesion causes fixed deficits, usually with other signs.', 'Third nerve palsies are fixed and usually affect the pupil.', 'Myopathy causes fixed, not fatigable, weakness and rarely starts in the eyes.'],
  fn: ['Ptosis that worsens with sustained upgaze and recovers with rest is fatigability.', 'A voice that fades with counting is fatigable bulbar weakness.', 'Normal pupils, sensation and reflexes exclude nerve and brainstem causes.', 'No fixed one-sided weakness argues against a structural lesion.'],
  w: 'In myasthenia gravis, antibodies reduce working acetylcholine receptors, so muscles that fire repeatedly, such as those of the eyelids and throat, tire quickly.',
  st: ['The weakness fluctuates and worsens with use.', 'Pupils, sensation and reflexes are normal.', 'That points to the neuromuscular junction.'],
  p: 'Ask about weakness that is worse in the evening; fatigability is the key clue.', g: ['nmj-compare', 'motor-unit']},
 'case-33': {ti: 'Weak legs and a dry mouth', k: 'Localize',
  s: 'A 66-year-old ex-smoker has found it harder to get out of chairs over three months and has a constantly dry mouth.',
  f: ['His hip and thigh muscles are weak', 'Reflexes are absent at rest but appear after he squeezes hard for ten seconds', 'His grip gets stronger for a few seconds as he keeps squeezing', 'Sensation is normal'],
  q: 'Where is the problem?',
  o: ['Nerve endings at the neuromuscular junction (Lambert–Eaton pattern)', 'Muscle receptors at the junction (myasthenia pattern)', 'Muscle (myopathy)', 'Spinal cord'],
  r: ['Best fit. Proximal weakness, a dry mouth and reflexes and strength that improve after brief effort are Lambert–Eaton syndrome, often linked to lung cancer in smokers.', 'Myasthenia worsens with effort and keeps normal reflexes.', 'Myopathy does not improve with effort or cause a dry mouth.', 'A cord lesion would cause brisk reflexes and a sensory level.'],
  fn: ['Proximal weakness with a dry mouth combines motor and autonomic involvement.', 'Reflexes that appear after brief effort are post-exercise facilitation.', 'Strength that improves briefly with effort is typical of a presynaptic disorder.', 'Normal sensation excludes a neuropathy.'],
  w: 'In Lambert–Eaton syndrome, antibodies block calcium channels in nerve endings, so too little acetylcholine is released. Brief effort builds up calcium and temporarily improves strength and reflexes.',
  st: ['Proximal weakness with no sensory loss suggests muscle or junction.', 'Reflexes and strength improve after effort.', 'With a dry mouth, that points to the presynaptic junction.'],
  p: 'In a smoker with Lambert–Eaton features, look for lung cancer.', g: ['nmj-compare', 'motor-unit']},
 'case-34': {ti: 'Trouble with stairs and high shelves', k: 'Localize',
  s: 'A 55-year-old woman has slowly found it harder to climb stairs and lift things onto high shelves over a year.',
  f: ['Both shoulders and hips are weak; her hands and feet are strong', 'Sensation is normal and reflexes are present', 'There is no drooping of the eyelids, twitching of muscles or upgoing toe', 'A blood test shows a raised muscle enzyme (creatine kinase)'],
  q: 'Where is the problem?',
  o: ['Muscle (myopathy)', 'Neuromuscular junction', 'Motor neurons in the spinal cord', 'Peripheral nerves'],
  r: ['Best fit. Symmetric shoulder and hip weakness with normal sensation and reflexes and a raised muscle enzyme points to muscle disease.', 'Junction disorders fluctuate and usually involve the eyes.', 'Motor neuron disease causes wasting and twitching.', 'Nerve disease usually starts distally with sensory loss and low reflexes.'],
  fn: ['Symmetric shoulder and hip weakness with strong hands and feet is a proximal pattern.', 'Normal sensation and reflexes argue against nerve disease.', 'No fatigable ptosis, twitching or upgoing toe exclude the junction, motor neurons and spinal cord.', 'A raised creatine kinase shows muscle fibres are damaged.'],
  w: 'Most myopathies weaken the large proximal muscles first. Damaged muscle fibres leak creatine kinase into the blood.',
  st: ['Weakness is proximal and symmetric.', 'Sensation and reflexes are normal.', 'A raised muscle enzyme supports myopathy.'],
  p: 'Ask about stairs and reaching up: they test the proximal muscles.', g: ['body-patterns', 'motor-unit', 'umn-lmn']},
 'case-35': {ti: 'A hand that overshoots', k: 'Localize',
  s: 'A 60-year-old man suddenly became clumsy with his left hand and keeps knocking his cup over. His strength feels normal.',
  f: ['His left finger overshoots your finger and his left heel slides off his shin', 'Rapid tapping and turning of the left hand is irregular', 'Feeling and position sense are normal', 'The clumsiness is the same whether or not he watches his hand'],
  q: 'Where is the lesion?',
  o: ['Left cerebellar hemisphere', 'Right cerebellar hemisphere', 'Right parietal lobe', 'Back of the spinal cord'],
  r: ['Best fit. Left limb overshoot and irregular rapid movements with normal strength and sensation come from the left cerebellar hemisphere.', 'Cerebellar hemispheres control the limbs on their own side.', 'A parietal lesion would cause sensory or spatial problems on the opposite side.', 'Dorsal column loss reduces position sense and improves when the limb is watched.'],
  fn: ['Overshooting the target is dysmetria, a cerebellar sign.', 'Irregular rapid movements are dysdiadochokinesia.', 'Normal position sense excludes sensory ataxia.', 'No improvement with vision supports a cerebellar cause.'],
  w: 'Each cerebellar hemisphere coordinates the limbs on its own side, because its pathways cross twice.',
  st: ['Clumsiness with normal strength is ataxia.', 'Position sense is normal, so it is cerebellar.', 'Limb ataxia is on the same side as the lesion.'],
  p: 'Cerebellar limb signs are on the same side as the lesion.', g: ['coordination']},
 'case-36': {ti: 'Swaying even when sitting', k: 'Localize',
  s: 'A 52-year-old man who drinks heavily walks with his feet wide apart and sways when sitting on the edge of the bed.',
  f: ['His trunk sways even when he sits with his eyes open', 'He walks on a wide base; his finger–nose test is only slightly off', 'Position and vibration sense are normal in the toes', 'He does not complain that the world bounces when he walks'],
  q: 'Where is the lesion?',
  o: ['Midline cerebellum (vermis)', 'One cerebellar hemisphere', 'Back of the spinal cord', 'Inner ears on both sides'],
  r: ['Best fit. Truncal sway and a wide-based gait with nearly normal limbs come from the midline cerebellum, often affected by alcohol.', 'A hemisphere lesion mainly causes one-sided limb clumsiness.', 'Dorsal column disease reduces position sense.', 'Bilateral inner ear loss makes the world bounce on walking.'],
  fn: ['Sway while seated points to the midline cerebellum.', 'A wide-based gait with near-normal limbs is the midline pattern.', 'Normal position sense excludes sensory ataxia.', 'No bouncing vision argues against inner ear loss.'],
  w: 'The vermis controls posture and the trunk, while the hemispheres coordinate the limbs.',
  st: ['The trunk and gait are affected more than the limbs.', 'Sensation is normal.', 'That is the midline cerebellum.'],
  p: 'Alcohol characteristically damages the front of the vermis, causing gait ataxia.', g: ['coordination']},
 'case-37': {ti: 'Bumping into people on both sides', k: 'Localize',
  s: 'A 45-year-old woman keeps bumping into people on both sides and has stopped driving. Her periods have stopped and she has headaches.',
  f: ['Each eye has lost the outer (temporal) half of its field', 'The inner halves are normal and the edge of the loss is the vertical midline', 'Eye movements are normal', 'Central vision is good'],
  q: 'Where is the lesion?',
  o: ['Optic chiasm', 'Both optic nerves', 'Left optic tract', 'Both occipital lobes'],
  r: ['Best fit. Loss of both outer half-fields is a bitemporal hemianopia from pressure on the centre of the chiasm, often from a pituitary tumour.', 'Optic nerve lesions reduce central vision and colour rather than halving the field.', 'An optic tract lesion removes the same half in both eyes.', 'Occipital lesions remove the same half in both eyes.'],
  fn: ['Loss of the outer half-field in each eye is a bitemporal hemianopia.', 'A sharp vertical edge shows a lesion where crossing fibres separate.', 'Normal eye movements mean the nearby nerves are spared.', 'Good central vision fits a lesion of crossing fibres only.'],
  w: 'Fibres from the inner half of each retina, which see the outer fields, cross in the chiasm. Pressure on the centre of the chiasm removes both outer fields.',
  st: ['Both outer fields are missing.', 'Only crossing fibres carry the outer fields.', 'They cross at the chiasm.'],
  p: 'Bitemporal field loss with hormone symptoms suggests a pituitary tumour.', g: ['field-defects', 'vision']},
 'case-38': {ti: 'Missing everything on the left', k: 'Localize',
  s: 'A 72-year-old man keeps walking into things on his left. Covering either eye, he still cannot see things to his left.',
  f: ['The left half of the field is missing in both eyes', 'In the left eye the outer half is lost; in the right eye the inner half is lost', 'Acuity and eye movements are normal', 'There is no weakness or numbness'],
  q: 'Where is the lesion?',
  o: ['Right side of the visual pathway behind the chiasm', 'Left optic nerve', 'Optic chiasm', 'Left side of the visual pathway behind the chiasm'],
  r: ['Best fit. Loss of the left half of space in both eyes is a left homonymous hemianopia, from a lesion behind the chiasm on the right side.', 'An optic nerve lesion affects one eye only.', 'A chiasmal lesion removes both outer halves.', 'A left-sided lesion would remove the right half of space.'],
  fn: ['Missing the left half in both eyes is a homonymous hemianopia.', 'The loss is the same side of space in each eye.', 'Normal acuity argues against optic nerve disease.', 'No other signs leave the exact level open.'],
  w: 'Behind the chiasm, each side of the visual pathway carries the opposite half of space from both eyes.',
  st: ['The same half is missing in both eyes.', 'So the lesion is behind the chiasm.', 'The left field is carried by the right pathway.'],
  p: 'A homonymous defect proves the side and that the lesion is behind the chiasm; other signs fix the level.', g: ['field-defects', 'vision']},
 'case-39': {ti: 'A gap in the top corner', k: 'Localize',
  s: 'A 54-year-old woman had a seizure. Afterwards she notices a gap in the upper right part of what she sees, with either eye.',
  f: ['The upper right quarter of the field is missing in both eyes', 'The lower right and the left fields are normal', 'Acuity is normal in each eye', 'There is no weakness'],
  q: 'Where is the lesion?',
  o: ['Left temporal lobe (Meyer loop)', 'Right temporal lobe', 'Left parietal lobe', 'Left optic nerve'],
  r: ['Best fit. An upper right quadrant loss in both eyes is "pie in the sky" from the left temporal lobe, where the Meyer loop carries the upper field.', 'A right temporal lesion removes the upper left quarter.', 'A left parietal lesion removes the lower right quarter.', 'An optic nerve lesion affects one eye only.'],
  fn: ['Upper right quarter loss in both eyes is a homonymous quadrantanopia.', 'Spared lower and left fields confirm a quarter-field defect.', 'Normal acuity excludes the optic nerves.', 'A seizure suggests a cortical or temporal lobe lesion.'],
  w: 'Fibres carrying the upper field loop forward through the temporal lobe (Meyer loop), so a temporal lesion removes the opposite upper quadrant.',
  st: ['The same quarter is lost in both eyes, behind the chiasm.', 'Upper quadrant means the temporal lobe.', 'Right field means the left side.'],
  p: '"Pie in the sky" is temporal; "pie on the floor" is parietal.', g: ['field-defects', 'vision']},
 'case-40': {ti: 'Painful eye with washed-out colours', k: 'Localize',
  s: 'A 28-year-old woman has had blurred vision in her right eye for four days. It hurts to move the eye, and red looks washed out.',
  f: ['Right eye acuity is reduced and colours look faded', 'When a light is swung from the left eye to the right, both pupils widen', 'Eye movements are full but painful; there is no droopy lid', 'The back of the eye looks normal and the left eye is normal'],
  q: 'Where is the lesion?',
  o: ['Right optic nerve', 'Right retina', 'Optic chiasm', 'Right third nerve'],
  r: ['Best fit. Reduced acuity and colour vision, a relative afferent pupil defect, pain on eye movement and a normal fundus point to the right optic nerve, as in optic neuritis.', 'Retinal disease usually shows on examination of the back of the eye.', 'A chiasmal lesion would affect the left eye too.', 'A third nerve lesion causes a droopy lid and eye movement problems, not loss of vision.'],
  fn: ['Reduced acuity and faded colours point to the optic nerve.', 'Pupils widening when the light reaches the right eye is a right relative afferent pupillary defect.', 'Pain on eye movement suggests inflammation of the optic nerve.', 'A normal retina and normal left eye place the lesion in the right optic nerve.'],
  w: 'An optic nerve lesion reduces acuity, colour vision and the light signal from that eye. The swinging light test compares the two eyes.',
  st: ['One eye has reduced vision and colour.', 'There is an afferent pupil defect on that side.', 'With a normal retina, it is the optic nerve.'],
  p: 'Painful visual loss with faded colours in a young adult suggests optic neuritis.', g: ['pupil-reflex', 'field-defects']},
 'case-041': {ti: 'Getting the sounds of words wrong', k: 'Localize',
  s: 'A 61-year-old lecturer can explain ideas well but keeps getting the sounds of words wrong ("spoot" for "spoon") and corrects himself. He cannot repeat a sentence.',
  f: ['Speech is fluent with sound errors in words', 'He understands conversation well', 'He repeatedly tries to correct himself; hearing is normal', 'Repeating a sentence is very poor'],
  q: 'What type of language problem is this?',
  o: ['Conduction aphasia', 'Wernicke aphasia', 'Broca aphasia', 'Dysarthria (speech muscles)'],
  r: ['Best fit. Fluent speech with sound errors, good understanding, self-correction and very poor repetition is conduction aphasia.', 'Wernicke aphasia has poor comprehension.', 'Broca aphasia is slow and effortful.', 'Dysarthria slurs speech evenly but does not change the sounds of words or repetition.'],
  fn: ['Fluent speech with sound errors suggests a problem with word sounds.', 'Good comprehension spares the Wernicke area.', 'Self-correction shows he knows the target word.', 'Very poor repetition is the hallmark of conduction aphasia.'],
  w: 'Conduction aphasia arises from damage to the connections between the posterior and frontal language areas, around the supramarginal gyrus and arcuate fasciculus.',
  st: ['Speech is fluent and comprehension good.', 'Repetition is the main failure.', 'That is conduction aphasia.'],
  p: 'Ask the person to repeat a sentence; it is the key test.', g: ['aphasia-tree', 'cortex']},
 'case-042': {ti: 'Long silences but perfect repetition', k: 'Discriminate',
  s: 'A 70-year-old woman barely speaks unless asked, gives one-word answers after long pauses, yet understands everything.',
  f: ['Spontaneous speech is sparse and slow to start', 'Her words are clearly pronounced', 'She can repeat a long sentence perfectly', 'She understands questions and commands'],
  q: 'What type of language problem is this?',
  o: ['Transcortical motor aphasia', 'Broca aphasia', 'Conduction aphasia', 'Wernicke aphasia'],
  r: ['Best fit. Sparse, hard-to-start speech with perfect repetition and good understanding is transcortical motor aphasia.', 'Broca aphasia impairs repetition.', 'Conduction aphasia is fluent with poor repetition.', 'Wernicke aphasia has poor comprehension.'],
  fn: ['Sparse speech that is hard to start is reduced initiation.', 'Clear pronunciation rules out dysarthria.', 'Perfect repetition spares the main language loop.', 'Good comprehension spares the posterior language area.'],
  w: 'Transcortical motor aphasia comes from frontal lesions outside the main language loop, often medial frontal, so repetition is preserved while starting speech is hard.',
  st: ['Speech is non-fluent.', 'Repetition is preserved.', 'Non-fluent with good repetition is transcortical motor aphasia.'],
  p: 'Preserved repetition separates transcortical aphasias from the classic types.', g: ['aphasia-tree', 'vascular']},
 'case-043': {ti: 'Repeats instructions but does not understand them', k: 'Discriminate',
  s: 'A 75-year-old man repeats your instructions back word for word but then does nothing, and cannot say what they meant.',
  f: ['He talks fluently but says little of meaning', 'He cannot point to objects you name', 'Hearing and alertness are normal', 'He repeats long sentences accurately'],
  q: 'What type of language problem is this?',
  o: ['Transcortical sensory aphasia', 'Wernicke aphasia', 'Conduction aphasia', 'Anomic aphasia'],
  r: ['Best fit. Fluent, empty speech with poor comprehension but intact repetition is transcortical sensory aphasia.', 'Wernicke aphasia also impairs repetition.', 'Conduction aphasia leaves comprehension intact.', 'Anomic aphasia preserves comprehension.'],
  fn: ['Fluent but empty speech is a fluent aphasia.', 'Poor word-to-object matching is poor comprehension.', 'Normal hearing makes this a language problem.', 'Accurate repetition spares the main language loop.'],
  w: 'Transcortical sensory aphasia separates the intact repetition loop from meaning, usually from posterior lesions outside the main language areas.',
  st: ['Speech is fluent and comprehension poor.', 'Repetition is intact.', 'That is transcortical sensory aphasia.'],
  p: 'Someone who repeats your words but cannot use them has a transcortical sensory pattern.', g: ['aphasia-tree']},
 'case-044': {ti: 'Can write but cannot read', k: 'Localize',
  s: 'A 67-year-old woman wrote a shopping list and then could not read it back. She also bumps into things on her right.',
  f: ['She understands speech and names objects normally', 'The right half of her field is missing in both eyes', 'She writes a dictated sentence correctly but cannot read it', 'Her strength and feeling are normal'],
  q: 'Where is the lesion?',
  o: ['Left occipital lobe and the back of the corpus callosum', 'Left angular gyrus', 'Left posterior temporal lobe', 'Right occipital lobe'],
  r: ['Best fit. Reading lost with writing preserved and a right field cut is alexia without agraphia, from the left occipital lobe plus the back of the corpus callosum (splenium).', 'Angular gyrus lesions impair both reading and writing.', 'A posterior temporal lesion impairs comprehension.', 'A right occipital lesion would cause a left field cut and would not stop reading.'],
  fn: ['Normal speech and naming show language itself works.', 'A right field cut shows the left occipital lobe is damaged.', 'Writing preserved while reading fails is alexia without agraphia.', 'Normal strength and feeling keep the lesion posterior.'],
  w: 'With the left occipital lobe damaged, written words reach only the right occipital lobe. If the splenium is also damaged, they cannot cross to the left-hemisphere language areas, so reading fails while writing is spared.',
  st: ['She can write but not read.', 'She has a right field cut.', 'That fits a left occipital lesion that also disconnects the right occipital lobe.'],
  p: 'Being unable to read what you just wrote is a striking disconnection sign.', g: ['vision', 'cortex']},
 'case-045': {ti: 'Cannot recognise a key by touch', k: 'Localize',
  s: 'With her eyes closed, a 59-year-old woman holds a key in her left hand and cannot say what it is. She names it immediately with her right hand or when she sees it.',
  f: ['Touch, vibration, position sense and two-point discrimination are normal in the left hand', 'She names objects instantly when she sees them', 'There is no weakness or neglect', 'The right hand recognises objects normally'],
  q: 'Where is the lesion?',
  o: ['Right parietal lobe (association cortex)', 'Right thalamus', 'Left parietal lobe', 'Right median nerve'],
  r: ['Best fit. Failing to recognise objects by touch in the left hand with normal basic sensation is astereognosis from the right parietal association cortex.', 'A thalamic lesion would reduce basic sensation.', 'A left parietal lesion would affect the right hand.', 'A median nerve lesion would reduce sensation in the fingers.'],
  fn: ['Normal basic and discriminative sensation show the pathways work.', 'Naming by sight shows the problem is not language or memory.', 'No weakness or neglect points to a small lesion.', 'A normal right hand confirms a one-sided problem.'],
  w: 'Recognising an object by touch requires the parietal association cortex to combine many sensory inputs. With basic sensation intact, astereognosis points to the opposite parietal lobe.',
  st: ['Basic sensation in the left hand is normal.', 'Recognition by touch fails.', 'That is a cortical sensory problem in the right parietal lobe.'],
  p: 'Only call it astereognosis when basic sensation is normal.', g: ['cortex']},
 'case-046': {ti: 'Ignoring the left, or blind to the left?', k: 'Discriminate',
  s: 'After a stroke, a 77-year-old man misses objects on his left. His attention wanders, so his visual field test is unreliable.',
  f: ['He feels a single touch on either hand', 'He has no major weakness', 'He understands instructions', 'You want to know whether this is neglect or simply a blind left half-field'],
  q: 'Which result would best show it is neglect?',
  o: ['He misses the left touch when both hands are touched together', 'He misses objects on the left with each eye covered', 'He reads more slowly near the left edge of the page', 'His searching improves when you remind him to look left'],
  r: ['Best fit. Missing the left touch only when both sides are touched (extinction) shows an attention problem that a blind half-field cannot explain.', 'Missing left objects in each eye fits a field cut as well.', 'Slow reading at the left edge also happens with a field cut.', 'Improvement with reminders is not specific.'],
  fn: ['Feeling single touches shows basic sensation is intact.', 'No weakness keeps the question on attention or vision.', 'He understands the tests.', 'The decision is between neglect and a field cut.'],
  w: 'Extinction means a stimulus is felt alone but lost when another competes on the other side, a sign of disordered attention rather than a sensory or visual loss.',
  st: ['Neglect and a field cut can both make him miss left objects.', 'Only neglect causes extinction of touch.', 'So test both hands together.'],
  p: 'Touch both sides at once; extinction separates neglect from a field cut.', g: ['cortex', 'field-defects']},
 'case-047': {ti: 'Cannot show how to salute', k: 'Localize',
  s: 'A 63-year-old man knows what a salute is but, asked to show one, makes clumsy wrong movements with either hand, even copying you.',
  f: ['His strength and coordination are normal', 'He recognises a toothbrush and knows what it is for', 'He understands the instruction', 'The errors happen with both hands'],
  q: 'Where is the lesion?',
  o: ['Left frontal and parietal lobes (praxis network)', 'Right parietal lobe (attention)', 'Cerebellum', 'Motor pathway in the spinal cord'],
  r: ['Best fit. Failure to perform learned gestures with both hands despite normal strength, coordination and understanding is apraxia from the left frontoparietal network.', 'Right parietal lesions cause neglect, not apraxia in both hands.', 'Cerebellar lesions cause overshoot and tremor.', 'Spinal cord lesions cause weakness.'],
  fn: ['Normal strength and coordination exclude a motor problem.', 'Recognising tools shows the idea of the action is intact.', 'Understanding the instruction excludes aphasia as the cause.', 'Both hands affected points to the left hemisphere, which guides both.'],
  w: 'Learned skilled movements are planned in a left frontoparietal network that guides both hands. Damage causes apraxia.',
  st: ['He has the strength and the understanding.', 'He cannot produce learned gestures.', 'That is apraxia, from the left frontoparietal network.'],
  p: 'Ask for a gesture and to copy one; apraxia is easy to miss.', g: ['cortex']},
 'case-048': {ti: 'Muddled sums and spelling', k: 'Predict',
  s: 'A 56-year-old accountant cannot do simple sums and makes spelling mistakes after a stroke in the left parietal lobe. Conversation is normal.',
  f: ['A scan shows a lesion in the lower left parietal lobe (angular gyrus)', 'He is alert and not confused', 'His vision is good', 'He also confuses his left and right'],
  q: 'Which other test is most likely to be abnormal?',
  o: ['Naming or pointing to particular fingers', 'Copying a 3D cube', 'Bisecting a horizontal line', 'Copying an unfamiliar hand gesture'],
  r: ['Best fit. Calculation and spelling errors with left–right confusion are three of the four Gerstmann features; the fourth is finger agnosia, tested by naming fingers.', 'Cube copying tests visuospatial skills, more linked to the right parietal lobe.', 'Line bisection tests neglect.', 'Gesture copying tests praxis.'],
  fn: ['A left angular gyrus lesion is the classic site of Gerstmann syndrome.', 'Alertness makes the problems focal.', 'Good vision rules out a visual cause.', 'Left–right confusion is another Gerstmann feature.'],
  w: 'Gerstmann syndrome combines poor calculation, poor writing, left–right confusion and finger agnosia from the dominant angular gyrus.',
  st: ['Three Gerstmann features are present.', 'The fourth is finger agnosia.', 'Test finger naming.'],
  p: 'Ask "show me your ring finger" when you suspect a dominant parietal lesion.', g: ['cortex']},
 'case-049': {ti: 'Numb body, normal face', k: 'Predict',
  s: 'A scan of a 64-year-old man with new numbness shows a tiny stroke in the right thalamus, in the part that relays body sensation. The part that relays the face is spared.',
  f: ['The motor fibres nearby are spared', 'He reports altered feeling', 'The lesion does not reach the cortex'],
  q: 'Which sensory pattern do you expect?',
  o: ['Loss on the left body with the face spared', 'Loss on the left face with the body spared', 'Loss on the right body with the face spared', 'Loss on both sides of the body'],
  r: ['Best fit. The body part of the thalamus (VPL) relays the opposite body; with the face part (VPM) spared, the face feels normal.', 'Face loss with body sparing would mean the face part is affected.', 'The thalamus relays the opposite side.', 'A one-sided lesion affects one side.'],
  fn: ['Spared motor fibres mean no weakness.', 'Altered feeling confirms a sensory relay lesion.', 'No cortical spread means only basic sensory loss.'],
  w: 'The ventral posterolateral (VPL) nucleus relays the opposite body and the ventral posteromedial (VPM) nucleus the face. A lesion limited to VPL spares the face.',
  st: ['The lesion is in the right sensory thalamus.', 'The thalamus serves the opposite side.', 'Only the body part is affected.'],
  p: 'Body and face relay in neighbouring thalamic nuclei, so they can be affected separately.', g: ['compact', 'sensory-pathways']},
 'case-050': {ti: 'Sleepy and forgetful after a deep stroke', k: 'Predict',
  s: 'A 59-year-old man was found very drowsy. A scan shows strokes on both sides of the middle (paramedian) thalamus.',
  f: ['The sensory relay nuclei at the sides are spared', 'The occipital lobes are normal', 'There is no clear one-sided weakness'],
  q: 'Which problems do you expect as he wakes up?',
  o: ['Reduced alertness and poor memory for new events', 'Loss of feeling down one side', 'A blind half-field', 'Clumsy limbs with normal memory'],
  r: ['Best fit. The paramedian thalamus is part of the arousal and memory circuits; damage on both sides causes drowsiness and memory loss.', 'One-sided sensory loss needs the lateral sensory nuclei.', 'A field cut needs the geniculate or occipital lobe.', 'Clumsy limbs with normal memory fits the cerebellum.'],
  fn: ['Spared sensory nuclei mean little sensory loss.', 'Normal occipital lobes mean no field cut.', 'No weakness spares the motor pathway.'],
  w: 'Medial and intralaminar thalamic nuclei help maintain arousal and connect memory circuits. Both sides together, often from a single artery, cause drowsiness and amnesia.',
  st: ['The lesion is in the middle thalamus on both sides.', 'These nuclei serve arousal and memory.', 'Expect drowsiness and memory loss.'],
  p: 'Unexplained drowsiness with memory loss can come from a small bilateral thalamic stroke.', g: ['compact']},
 'case-051': {ti: 'Slurred speech and a crooked smile', k: 'Predict',
  s: 'A scan of a 66-year-old woman shows a tiny stroke in the bend (genu) of the left internal capsule. Language is normal.',
  f: ['Language tests are normal', 'There is no cortical damage', 'Her speech sounds slurred'],
  q: 'Which other deficit is most likely?',
  o: ['Weakness of the right lower face', 'Right leg weaker than the right face', 'A right half-field loss without weakness', 'Right body numbness without slurred speech'],
  r: ['Best fit. Fibres to the face and speech muscles pass through the genu, so a genu lesion causes slurred speech and opposite lower face weakness.', 'Leg weakness needs the back of the posterior limb or the medial cortex.', 'A field cut needs the optic radiation behind the lentiform nucleus.', 'Body numbness needs the sensory fibres behind the motor fibres.'],
  fn: ['Normal language makes aphasia unlikely.', 'No cortical lesion keeps the problem deep.', 'Slurred speech is dysarthria.'],
  w: 'Corticobulbar fibres for the face, tongue and throat pass through the genu of the internal capsule.',
  st: ['The lesion is in the genu.', 'The genu carries face and speech fibres.', 'Expect slurred speech and lower face weakness.'],
  p: 'Dysarthria with facial weakness can come from a tiny capsular stroke.', g: ['compact']},
 'case-052': {ti: 'Wild flinging of an arm', k: 'Predict',
  s: 'A 71-year-old woman with diabetes suddenly develops wild, flinging movements of her left arm and leg. A scan shows a small stroke in the right subthalamic nucleus.',
  f: ['The movements are irregular, not rhythmic', 'Her strength is normal between movements', 'There is no sensory level'],
  q: 'What explains the movements?',
  o: ['Less brake on the motor thalamus, so it overdrives the cortex', 'More brake on the motor thalamus', 'Damage to the motor pathway in the capsule', 'Overactivity of the subthalamic nucleus'],
  r: ['Best fit. The subthalamic nucleus normally drives the globus pallidus, which brakes the motor thalamus. When it is damaged, the brake weakens and involuntary flinging (hemiballismus) appears on the opposite side.', 'More braking reduces movement, as in Parkinson disease.', 'Motor pathway damage causes weakness, not extra movement.', 'A stroke reduces, not increases, subthalamic activity.'],
  fn: ['Irregular flinging is ballism.', 'Normal strength shows the motor pathway works.', 'No sensory level excludes the cord.'],
  w: 'Basal ganglia circuits balance movement. Loss of subthalamic output reduces pallidal inhibition of the motor thalamus, releasing unwanted movements on the opposite side.',
  st: ['The movements are on the left, from a right-sided lesion.', 'The subthalamic nucleus is part of the braking circuit.', 'Losing it releases movement.'],
  p: 'Hemiballismus classically follows a lesion of the opposite subthalamic nucleus.', g: ['compact']},
 'case-053': {ti: 'Only one eye can move sideways', k: 'Localize',
  s: 'A 33-year-old woman with multiple sclerosis has new double vision. Neither eye will look to the right. Looking left, only her left eye moves out, flickering.',
  f: ['Up and down eye movements are normal', 'Both eyes turn in when she looks at her nose', 'There is no droopy lid', 'The right eye does not move inward when she looks left'],
  q: 'Where is the lesion?',
  o: ['Right sixth nerve nucleus area plus the right MLF (one-and-a-half syndrome)', 'Left MLF only', 'Both sixth nerves', 'Right third nerve'],
  r: ['Best fit. Loss of gaze to the right (right sixth nucleus) plus failure of the right eye to move in on left gaze (right MLF) is the one-and-a-half syndrome in the right pons.', 'A left MLF lesion would affect the left eye moving in.', 'Sixth nerve lesions spare inward movement.', 'A third nerve lesion would cause a droopy lid and stop convergence.'],
  fn: ['Normal vertical movement keeps the midbrain intact.', 'Normal convergence shows the inward-moving muscles work.', 'No droopy lid excludes a third nerve palsy.', 'Right eye failing to move in on left gaze is a right MLF sign.'],
  w: 'Damage to the right sixth nucleus stops both eyes looking right (the "one"); the neighbouring right MLF stops the right eye moving in on left gaze (the "half"). Only left eye abduction remains.',
  st: ['There is a gaze palsy to the right.', 'There is also a right internuclear problem.', 'Both lie in the right pons.'],
  p: 'The one-and-a-half syndrome localises precisely to one side of the lower pons.', g: ['gaze-circuit']},
 'case-054': {ti: 'An eye that will not look out', k: 'Discriminate',
  s: 'A 48-year-old man\'s left eye cannot look out to the left. You want to know whether the problem is the sixth nerve itself or its nucleus in the pons.',
  f: ['Nothing is mechanically restricting the eye', 'He follows instructions well', 'Up and down movements are full'],
  q: 'Which finding would point to the nucleus?',
  o: ['The right eye also fails to move in when he looks left', 'Double vision is worse looking into the distance', 'The eyes cross more when he looks left', 'Vision in the left eye is normal'],
  r: ['Best fit. The nucleus drives both eyes to the left, so if the right eye also fails to move in, it is a gaze palsy from the nucleus.', 'Worse distance double vision happens with any sixth nerve weakness.', 'Increased crossing looking left also happens with any sixth nerve weakness.', 'Normal vision is expected either way.'],
  fn: ['No restriction means a neural cause.', 'Cooperation is good, so the test is reliable.', 'Full vertical movement spares III and IV.'],
  w: 'The sixth nucleus contains motor neurons for the same-side lateral rectus and interneurons that, through the opposite MLF, move the other eye inward. A nuclear lesion therefore causes a gaze palsy.',
  st: ['A nerve lesion affects one eye.', 'A nucleus lesion affects both eyes looking to that side.', 'Check whether the other eye moves in.'],
  p: 'When one eye fails to abduct, always watch the other eye.', g: ['gaze-circuit', 'eye-muscles']},
 'case-055': {ti: 'Facial palsy and cannot look left', k: 'Localize',
  s: 'A 41-year-old woman cannot close her left eye or wrinkle her left forehead, and neither eye will look to the left.',
  f: ['Both eyes look right normally', 'Hearing is normal', 'Arm and leg strength are normal'],
  q: 'Where is the lesion?',
  o: ['Back of the left lower pons (facial colliculus)', 'Front of the left lower pons', 'Left cerebellopontine angle', 'Left facial nerve outside the brainstem'],
  r: ['Best fit. A left peripheral facial palsy with a gaze palsy to the left and normal limbs comes from the back of the left pons, where the facial nerve loops around the sixth nucleus.', 'A front (ventral) lesion would weaken the opposite limbs and cause a sixth nerve, not a gaze, palsy.', 'A mass at the cerebellopontine angle usually affects hearing and does not cause a gaze palsy.', 'A facial nerve lesion would not affect eye movements.'],
  fn: ['Normal right gaze shows the problem is limited to the left gaze system.', 'Normal hearing argues against the cerebellopontine angle.', 'Normal limbs spare the motor pathway in the front of the pons.'],
  w: 'In the back of the lower pons, the facial nerve fibres loop around the sixth nucleus (facial colliculus). A lesion here causes a same-side facial palsy and a gaze palsy toward that side.',
  st: ['A peripheral facial palsy and a gaze palsy on the same side.', 'Both structures meet at the facial colliculus.', 'Normal limbs place it at the back of the pons.'],
  p: 'A gaze palsy with a same-side facial palsy points to the facial colliculus.', g: ['gaze-circuit', 'facial', 'brainstem-rule']},
 'case-056': {ti: 'Cannot look up', k: 'Localize',
  s: 'A 19-year-old man with headaches cannot look up. When he tries, his eyes pull in and jerk back.',
  f: ['Side-to-side eye movements are normal', 'Neither eye rests down and out', 'His pupils react poorly to light but constrict when he looks at something close'],
  q: 'Where is the lesion?',
  o: ['Top and back of the midbrain', 'Front of the midbrain', 'Back of the pons', 'Both cavernous sinuses'],
  r: ['Best fit. Loss of upgaze, convergence–retraction jerks and pupils that react to near but not light (Parinaud syndrome) come from the dorsal midbrain, often compressed by a pineal mass.', 'Front midbrain lesions cause a third nerve palsy with weakness.', 'Pontine lesions affect side-to-side gaze.', 'Cavernous sinus lesions cause nerve palsies, not loss of upgaze with this pupil pattern.'],
  fn: ['Normal side-to-side gaze spares the pons.', 'No down-and-out eye excludes a third nerve palsy.', 'Pupils reacting to near but not light is light–near dissociation.'],
  w: 'The dorsal midbrain near the posterior commissure controls upgaze and the pupil light reflex. Compression causes Parinaud syndrome.',
  st: ['Upgaze is lost.', 'The pupils react to near but not light.', 'Both point to the dorsal midbrain.'],
  p: 'A young person with headache and loss of upgaze needs imaging for a pineal region mass.', g: ['pupil-reflex', 'cranial']},
 'case-057': {ti: 'Cannot look down to read', k: 'Discriminate',
  s: 'A 68-year-old man keeps tripping on stairs because he cannot look down. You want to know whether the problem is above the eye movement nuclei.',
  f: ['There is no droopy lid', 'His pupils react normally', 'Side-to-side gaze is mostly preserved'],
  q: 'Which finding would show the problem is above the nuclei?',
  o: ['His eyes move down fully when you tilt his head back (doll\'s-eye reflex)', 'Reflex and voluntary downgaze are both absent', 'Only one eye fails to look down and in', 'Covering one eye changes the limitation'],
  r: ['Best fit. If reflex eye movements go further than voluntary ones, the nuclei and nerves work and the problem is above them (supranuclear), as in progressive supranuclear palsy.', 'Loss of both points to the nuclei, nerves or muscles.', 'One eye failing to look down and in is a fourth nerve problem.', 'A change with covering one eye suggests a muscle imbalance.'],
  fn: ['No droopy lid makes a third nerve palsy unlikely.', 'Normal pupils argue against a third nerve lesion.', 'Preserved side gaze limits the problem to vertical movement.'],
  w: 'Supranuclear lesions affect the commands for voluntary eye movement, while reflex pathways to intact nuclei still work.',
  st: ['Voluntary downgaze is limited.', 'Test reflex movements by moving the head.', 'If they work, the lesion is above the nuclei.'],
  p: 'Falls on stairs with slow downgaze suggest progressive supranuclear palsy.', g: ['gaze-circuit', 'eye-muscles']},
 'case-058': {ti: 'Vertigo, deafness and a crossed numbness', k: 'Localize',
  s: 'A 62-year-old man has sudden spinning vertigo, deafness in his right ear and a drooping right face.',
  f: ['The right side of his face is numb to pinprick', 'His left arm, trunk and leg are numb to pinprick', 'His voice and palate are normal', 'His right arm is clumsy'],
  q: 'Where is the lesion?',
  o: ['Right side of the lower pons', 'Right lateral medulla', 'Right inner ear only', 'Right internal capsule'],
  r: ['Best fit. Hearing loss, facial weakness and a crossed pain loss with a normal palate point to the right lateral lower pons (often the AICA territory).', 'The lateral medulla usually causes hoarseness and spares hearing and facial movement.', 'An inner ear problem cannot cause numbness of the face and opposite body.', 'A capsular lesion would cause opposite-side signs, not same-side deafness.'],
  fn: ['Right face numbness is the right trigeminal pathway.', 'Left body numbness is the right spinothalamic tract.', 'A normal voice spares the medulla.', 'Right arm clumsiness adds cerebellar connections on the same side.'],
  w: 'The lateral lower pons holds the facial and hearing nuclei and fibres alongside the trigeminal and spinothalamic pathways and cerebellar connections.',
  st: ['A crossed sensory pattern means the brainstem.', 'Deafness and facial weakness add pontine structures.', 'A normal voice keeps it above the medulla.'],
  p: 'Sudden deafness with brainstem signs is a stroke until proved otherwise.', g: ['crossed', 'brainstem-rule']},
 'case-059': {ti: 'Which sign proves the medulla?', k: 'Discriminate',
  s: 'A 73-year-old woman has a weak right arm and leg and cannot feel vibration in them. Her face and eyes are normal. You suspect a left medullary stroke.',
  f: ['There is no aphasia or neglect', 'Pain and temperature feel normal', 'You need one sign that pins the lesion to the medulla'],
  q: 'Which finding would best support the left medulla?',
  o: ['Her tongue is thin on the left and pushes to the left', 'Her right lower face is weak with the forehead spared', 'Her whole left face is weak', 'Her left eye does not move in when she looks right'],
  r: ['Best fit. A left lower motor neuron tongue palsy is the medial medullary sign that fixes the level.', 'A central facial palsy points above the facial nucleus, not the medulla.', 'A whole-face palsy is a pontine or facial nerve sign.', 'An eye that does not adduct is an MLF sign in the pons or midbrain.'],
  fn: ['No aphasia or neglect argues against the cortex.', 'Normal pain sensation fits the medial, not lateral, medulla.', 'Weakness and vibration loss alone can come from many levels.'],
  w: 'The medial medulla contains the hypoglossal nerve next to the pyramid and medial lemniscus. A same-side tongue palsy is the sign that places the lesion there.',
  st: ['Weakness and vibration loss could be at many levels.', 'A cranial nerve sign is needed to fix the level.', 'XII is the medullary nerve beside these tracts.'],
  p: 'Look at the tongue in every patient with a brainstem syndrome.', g: ['brainstem-rule', 'cranial']},
 'case-060': {ti: 'Both eyes lag moving inward', k: 'Localize',
  s: 'A 30-year-old man with multiple sclerosis has double vision. When he looks to either side, the eye moving inward lags and the other eye jerks.',
  f: ['Up and down movements are full', 'Both eyes turn in normally to look at his nose', 'His eyelids do not tire with repeated testing'],
  q: 'Where is the lesion?',
  o: ['Both medial longitudinal fasciculi (bilateral INO)', 'Both sixth nerve nuclei', 'Both third nerves', 'Neuromuscular junction'],
  r: ['Best fit. Slow adduction of either eye on side gaze with preserved convergence is bilateral internuclear ophthalmoplegia from both MLFs, typical of multiple sclerosis.', 'Sixth nucleus lesions cause gaze palsies.', 'Third nerve lesions would affect convergence, lids and vertical movements.', 'Junction disorders fatigue and are not limited to adduction on side gaze.'],
  fn: ['Full vertical movement spares the midbrain nuclei.', 'Normal convergence shows the inward-moving muscles work.', 'No fatigue argues against myasthenia.'],
  w: 'Each MLF carries the signal for one eye to move inward on side gaze. Damage to both causes bilateral internuclear ophthalmoplegia.',
  st: ['Either eye lags moving inward on side gaze.', 'Convergence is normal.', 'That is the MLF on both sides.'],
  p: 'Bilateral INO in a young adult strongly suggests multiple sclerosis.', g: ['gaze-circuit']},
 'case-061': {ti: 'Paralysed eye and a numb forehead', k: 'Localize',
  s: 'A 58-year-old woman has a painful right eye that has stopped moving over weeks, with numbness of her right forehead and cheek. Her vision is fine.',
  f: ['The right eye cannot move in any direction and the lid droops', 'The right forehead and cheek are numb', 'Acuity, colour vision and the optic disc are normal'],
  q: 'Where is the lesion?',
  o: ['Right cavernous sinus', 'Right orbital apex', 'Right midbrain', 'Right superior orbital fissure'],
  r: ['Best fit. Third, fourth and sixth nerve palsies with forehead and cheek numbness (V1 and V2) and normal vision point to the cavernous sinus.', 'The orbital apex would usually affect the optic nerve.', 'Midbrain lesions do not numb the face or affect VI.', 'The superior orbital fissure does not carry V2 (cheek).'],
  fn: ['III, IV and VI together suggest a site where they travel side by side.', 'Forehead and cheek numbness add V1 and V2, which run in the sinus wall.', 'Normal vision spares the optic nerve.'],
  w: 'The cavernous sinus contains III, IV, V1 and V2 in its wall and VI beside the carotid artery. The optic nerve lies outside it.',
  st: ['Several eye nerves are affected on one side.', 'V1 and V2 are numb.', 'With vision spared, that is the cavernous sinus.'],
  p: 'Cheek numbness (V2) helps place a multiple-nerve palsy in the cavernous sinus.', g: ['cavernous-sinus', 'eye-muscles']},
 'case-062': {ti: 'Losing vision and eye movement together', k: 'Localize',
  s: 'A 52-year-old man\'s left eye has gradually stopped moving properly while its vision has faded.',
  f: ['The left pupil shows an afferent defect on the swinging light test', 'Left acuity and colour vision are reduced', 'The left forehead is numb but the cheek feels normal'],
  q: 'Where is the lesion?',
  o: ['Left orbital apex', 'Left cavernous sinus', 'Left optic nerve alone', 'Left midbrain'],
  r: ['Best fit. Optic nerve loss with eye movement problems and forehead (V1) numbness, sparing the cheek (V2), points to the orbital apex.', 'A cavernous sinus lesion usually spares vision and may numb the cheek.', 'An optic nerve lesion alone would not affect eye movements or the forehead.', 'A midbrain lesion would not affect vision this way or numb the forehead.'],
  fn: ['An afferent pupil defect means the left optic nerve.', 'Reduced acuity and colour confirm optic nerve involvement.', 'V1 numbness with V2 spared fits the orbit rather than the sinus.'],
  w: 'At the orbital apex, the optic nerve and the nerves to the eye muscles and forehead pass together. V2 leaves the skull separately, so the cheek is spared.',
  st: ['Vision and eye movements fail together.', 'The forehead is numb but the cheek is not.', 'That fits the orbital apex.'],
  p: 'Vision loss plus eye movement palsy suggests the orbital apex rather than the cavernous sinus.', g: ['cavernous-sinus', 'pupil-reflex']}
});
Object.assign(window.NL_CASES_V2, {
 'case-063': {ti: 'No blink when one eye is touched', k: 'Localize',
  s: 'A 46-year-old man has numbness of his left forehead after shingles. Touching his left cornea with cotton wool makes neither eye blink; touching the right cornea makes both blink.',
  f: ['He can close both eyes tightly on command', 'There is no injury to the eye and no anaesthetic drops', 'His left forehead feels numb'],
  q: 'Which part of the blink reflex has failed?',
  o: ['The sensory side on the left (ophthalmic branch of the trigeminal nerve)', 'The motor side on the left (facial nerve)', 'The sensory side on the right', 'The motor side on the right'],
  r: ['Best fit. Neither eye blinks from the left, but both blink from the right, and the forehead is numb: the left trigeminal sensory limb has failed.', 'A left facial lesion would leave the right eye blinking when the left cornea is touched.', 'The right sensory side works, because touching the right cornea gives a normal blink.', 'Both eyes blink from the right, so the right motor side works.'],
  fn: ['Strong voluntary eye closure shows both facial nerves work.', 'No local cause means the reflex pathway itself is affected.', 'Left forehead numbness points to the left ophthalmic (V1) branch.'],
  w: 'The corneal reflex has a trigeminal (V1) sensory limb and facial motor limbs to both eyes. If touching one side gives no blink in either eye, that side\'s sensory limb has failed.',
  st: ['Touching the left side fails in both eyes.', 'Touching the right side works in both eyes.', 'So the left sensory limb is at fault.'],
  p: 'Test both corneas and watch both eyes to separate the sensory and motor limbs.', g: ['facial', 'cranial']},
 'case-064': {ti: 'Blink after a facial palsy', k: 'Predict',
  s: 'A 39-year-old woman has a right Bell palsy. Her facial sensation is normal on both sides.',
  f: ['She cannot close her right eye fully', 'Her left eye closes normally', 'Corneal sensation is normal on both sides'],
  q: 'What happens when you touch either cornea?',
  o: ['The left eye blinks; the right blink is weak or absent', 'Both eyes blink only when the left cornea is touched', 'Both eyes blink only when the right cornea is touched', 'The right eye blinks; the left blink is weak'],
  r: ['Best fit. Either cornea triggers the reflex, but only the left eye closes well because the right facial nerve is weak.', 'Sensation is intact on both sides, so either cornea triggers the reflex.', 'The same: touching either side triggers it.', 'The right eye is the weak one.'],
  fn: ['A weak right eye closure is the right facial motor limb.', 'Normal left closure shows the left motor limb works.', 'Normal sensation means either cornea can trigger the reflex.'],
  w: 'Each cornea triggers a blink in both eyes. With a right facial palsy, touching either cornea gives a normal left blink and a weak right blink.',
  st: ['The sensory limbs work on both sides.', 'The right motor limb is weak.', 'So the right blink is weak whichever side is touched.'],
  p: 'In Bell palsy the eye may not close, so protect the cornea.', g: ['facial']},
 'case-065': {ti: 'Double vision going down stairs', k: 'Localize',
  s: 'A 51-year-old man hit his head in a cycling accident. Since then he sees double, one image above the other, especially reading and going down stairs. He tilts his head to the left.',
  f: ['His right eye sits higher than the left, more when he looks left and when he tilts his head right', 'His right eye moves down poorly when it is turned in', 'Side-to-side movements and pupils are normal'],
  q: 'Which muscle is weak?',
  o: ['Right superior oblique (fourth nerve)', 'Right inferior rectus', 'Left superior rectus', 'Right lateral rectus'],
  r: ['Best fit. A higher right eye that worsens looking left and on right head tilt, with poor downward movement when turned in, is right superior oblique weakness, often after head injury.', 'Inferior rectus weakness is worst looking down and out.', 'Left superior rectus weakness lowers the left eye, with a different head tilt pattern.', 'Lateral rectus weakness causes side-by-side, not vertical, double vision.'],
  fn: ['A higher right eye, worse looking left and on right head tilt, is the right fourth nerve pattern.', 'Poor depression when the eye is turned in is the superior oblique action.', 'Normal horizontal movement spares III and VI.'],
  w: 'The superior oblique depresses the eye best when it is turned in. The fourth nerve has a long course and is often damaged by head injury. People tilt their head away from the weak side to fuse the images.',
  st: ['Vertical double vision worst reading and on stairs means looking down.', 'The right eye fails to depress when turned in.', 'That muscle is the right superior oblique.'],
  p: 'A head tilt away from the side of a higher eye suggests a fourth nerve palsy.', g: ['eye-muscles']},
 'case-066': {ti: 'Hoarse voice and a weak shoulder', k: 'Predict',
  s: 'A 60-year-old man has been hoarse for months. His left palate is weak, his left shoulder droops and the muscle in his left neck is thin.',
  f: ['The back of his throat is numb on the left', 'His tongue is normal', 'There are no crossed or long-tract signs'],
  q: 'Which new sign would mean the problem has spread beyond the jugular foramen?',
  o: ['Wasting and weakness of the left side of the tongue', 'More weakness of the left palate', 'More drooping of the left shoulder', 'More numbness at the back of the throat'],
  r: ['Best fit. IX, X and XI leave the skull together through the jugular foramen; XII (the tongue) leaves separately, so tongue weakness means spread beyond it.', 'More palatal weakness is more X involvement.', 'More shoulder weakness is more XI involvement.', 'More throat numbness is more IX involvement.'],
  fn: ['Throat numbness is IX.', 'A normal tongue spares XII.', 'No long-tract signs keep the problem outside the brainstem.'],
  w: 'IX, X and XI pass through the jugular foramen; XII passes through the nearby hypoglossal canal.',
  st: ['IX, X and XI are affected together.', 'They share the jugular foramen.', 'XII nearby would show spread.'],
  p: 'Several lower cranial nerves on one side suggest a skull-base lesion.', g: ['cranial']},
 'case-067': {ti: 'A small pupil and a droopy lid', k: 'Discriminate',
  s: 'A 44-year-old woman noticed her left eyelid drooping slightly and her left pupil looking smaller after neck pain began.',
  f: ['The size difference between the pupils is bigger in dim light', 'Both pupils shrink to bright light', 'The lid does not get worse with use'],
  q: 'Which finding confirms the sympathetic pathway is affected?',
  o: ['The left pupil is slow to widen when the lights are dimmed', 'The left pupil is slow to shrink to bright light', 'The left pupil is slow to shrink when looking at something close', 'The left lid droops more after looking up for a minute'],
  r: ['Best fit. Sympathetic fibres widen the pupil, so a pupil that lags when the light is dimmed (dilation lag) confirms a Horner syndrome.', 'Slow shrinking to light is a parasympathetic problem.', 'Slow near shrinking is also parasympathetic.', 'Worsening ptosis with use is fatigability, a junction sign.'],
  fn: ['A bigger difference in the dark shows the small pupil fails to widen.', 'Normal shrinking to light shows the parasympathetic pathway works.', 'No fatigue argues against myasthenia.'],
  w: 'Sympathetic fibres drive the pupil dilator and a small lid muscle. Without them the pupil is small, widens slowly in the dark, and the lid droops slightly. Neck pain raises concern for carotid dissection.',
  st: ['A small pupil with a mild droop suggests Horner syndrome.', 'The difference grows in the dark.', 'A dilation lag confirms it.'],
  p: 'New Horner syndrome with neck pain needs urgent assessment for carotid dissection.', g: ['horner', 'pupil-reflex']},
 'case-068': {ti: 'Both optic nerves equally damaged', k: 'Predict',
  s: 'A 37-year-old woman has lost central and colour vision equally in both eyes. A specialist confirms both optic nerves are damaged to the same degree.',
  f: ['Both eyes are equally affected', 'The iris and pupil nerves work normally', 'Both pupils still react a little to light'],
  q: 'What will the swinging light test show?',
  o: ['No relative defect, despite the damage', 'A relative defect in the right eye', 'A relative defect in the left eye', 'Relative defects in each eye alternately'],
  r: ['Best fit. The swinging light test compares the two eyes; when both are equally damaged there is no difference to detect.', 'There is no asymmetry to create a right-sided defect.', 'There is no asymmetry to create a left-sided defect.', 'The test is a comparison; it cannot show defects in both eyes at once.'],
  fn: ['Equal damage leaves no difference between the eyes.', 'Normal pupil nerves mean the pupils respond to whatever light signal arrives.', 'Some response remains in both eyes.'],
  w: 'A relative afferent pupillary defect appears only when one optic nerve conducts less than the other.',
  st: ['The test compares the eyes.', 'The eyes are equal.', 'So no relative defect appears.'],
  p: 'A normal swinging light test does not exclude damage to both optic nerves.', g: ['pupil-reflex']},
 'case-069': {ti: 'A half-field loss with a pupil clue', k: 'Localize',
  s: 'A 50-year-old man has lost the right half of his vision in both eyes. His acuity is good and the backs of his eyes look normal.',
  f: ['When a light is swung to the right eye, both pupils widen slightly', 'There is no separate optic nerve disease', 'The missing half-fields are not identical in the two eyes'],
  q: 'Where on the left side is the lesion?',
  o: ['Left optic tract', 'Left temporal lobe', 'Left parietal lobe', 'Left occipital lobe'],
  r: ['Best fit. A right half-field loss with a pupil defect in the right eye and unequal defects points to the left optic tract, which still carries pupil fibres.', 'Temporal lobe lesions spare the pupils and usually cause upper quadrant loss.', 'Parietal lesions spare the pupils.', 'Occipital lesions spare the pupils and give matching defects.'],
  fn: ['A pupil defect with a half-field loss suggests the lesion is before the pupil fibres leave the pathway.', 'No optic nerve disease means the field lesion causes the pupil defect.', 'Unequal defects are typical of the optic tract.'],
  w: 'Pupil fibres leave the optic tract before the lateral geniculate. A tract lesion therefore causes a pupil defect (in the opposite eye) as well as a half-field loss, while lesions further back spare the pupils.',
  st: ['A right half-field loss means the left pathway.', 'A pupil defect means before the geniculate.', 'That is the optic tract.'],
  p: 'A pupil defect with a homonymous hemianopia points to the optic tract.', g: ['field-defects', 'pupil-reflex', 'vision']},
 'case-070': {ti: 'One eye badly affected, the other slightly', k: 'Localize',
  s: 'A 56-year-old woman has severe loss of central vision in her left eye. Testing also finds a small gap in the upper outer field of her right eye.',
  f: ['There is a left afferent pupil defect', 'Right central vision is normal', 'The backs of both eyes look normal'],
  q: 'Where is the lesion?',
  o: ['Where the left optic nerve joins the chiasm', 'Left optic nerve in the orbit', 'Centre of the chiasm', 'Left optic tract'],
  r: ['Best fit. Severe left optic nerve loss plus a small right upper outer defect is a junctional scotoma, from a lesion where the left optic nerve meets the chiasm.', 'An orbital lesion would affect only the left eye.', 'A central chiasmal lesion gives both outer half-fields without severe one-eye loss.', 'An optic tract lesion gives matching half-fields in both eyes.'],
  fn: ['A left pupil defect means the left optic nerve.', 'Normal right central vision shows the right nerve itself is spared.', 'Normal retinas point to the optic pathway.'],
  w: 'Right-eye fibres for the upper outer field cross at the front of the chiasm near the left optic nerve. A lesion here damages both.',
  st: ['The left optic nerve is badly affected.', 'A small right-eye defect is also present.', 'Both meet at the junction with the chiasm.'],
  p: 'Always test the other eye\'s field when one optic nerve fails.', g: ['field-defects', 'vision']},
 'case-071': {ti: 'Missing the lower left corner', k: 'Localize',
  s: 'A 66-year-old woman misses things in the lower left part of her vision. She also has trouble drawing and ignores a touch on her left when both hands are touched.',
  f: ['Her pupils react normally', 'Her drawing of a clock is badly arranged', 'Eye movements are normal'],
  q: 'Where is the lesion?',
  o: ['Right parietal lobe', 'Right temporal lobe', 'Right optic tract', 'Left parietal lobe'],
  r: ['Best fit. A left lower quadrant loss with extinction and poor drawing comes from the right parietal lobe, through which the upper optic radiation passes.', 'A temporal lesion removes the upper quadrant.', 'An optic tract lesion usually causes a pupil defect and a half-field loss.', 'A left parietal lesion would affect the right lower quadrant.'],
  fn: ['Normal pupils place the lesion behind the optic tract.', 'Poor drawing is a right parietal sign.', 'Normal eye movements spare the midbrain.'],
  w: 'The upper fibres of the optic radiation, carrying the lower field, pass through the parietal lobe. A right parietal lesion causes a left lower quadrant loss with neglect and visuospatial problems.',
  st: ['A lower quadrant loss means the parietal lobe.', 'Neglect and poor drawing are right parietal signs.', 'So the right parietal lobe.'],
  p: 'Combine field and non-visual signs to place the lesion.', g: ['field-defects', 'cortex']},
 'case-072': {ti: 'After surgery on the temporal lobe', k: 'Predict',
  s: 'A 34-year-old man had surgery on the front of his left temporal lobe for epilepsy.',
  f: ['His eyes are normal', 'His optic nerves are normal', 'The parietal lobe was not touched'],
  q: 'Which field loss is he most likely to have?',
  o: ['Loss of the upper right quarter in both eyes', 'Loss of the lower right quarter in both eyes', 'Loss of the upper left quarter in both eyes', 'Loss of the whole right half in both eyes'],
  r: ['Best fit. The Meyer loop runs through the front of the temporal lobe carrying the upper field, so a left temporal lesion removes the upper right quarter.', 'Lower quadrant loss needs the parietal fibres.', 'A left lesion affects the right field.', 'A whole half-field loss needs damage to all the fibres.'],
  fn: ['Normal eyes keep the problem behind them.', 'Normal optic nerves exclude a one-eye defect.', 'An untouched parietal lobe spares the lower field fibres.'],
  w: 'The Meyer loop carries upper-field fibres forward through the temporal lobe, so it is vulnerable to temporal surgery.',
  st: ['The surgery affects the left temporal lobe.', 'The temporal lobe carries the upper field.', 'Expect upper right quadrant loss.'],
  p: 'Warn people before temporal lobe surgery about upper quadrant field loss.', g: ['field-defects', 'vision']},
 'case-073': {ti: 'Half-field loss with central vision kept', k: 'Localize',
  s: 'A 70-year-old man has lost the left half of his vision in both eyes, but he can still read the middle of a line.',
  f: ['The missing half is identical in both eyes, and central vision is spared', 'His pupils react normally', 'There is no neglect or numbness'],
  q: 'Where is the lesion?',
  o: ['Right occipital lobe (visual cortex)', 'Right optic tract', 'Right temporal lobe', 'Right parietal lobe'],
  r: ['Best fit. Identical half-fields with central vision spared and no other signs point to the right occipital cortex, often a posterior cerebral artery stroke.', 'Optic tract lesions give unequal defects and a pupil defect.', 'Temporal lesions usually remove the upper quadrant.', 'Parietal lesions usually remove the lower quadrant and bring neglect.'],
  fn: ['Identical defects with central sparing point to the occipital cortex.', 'Normal pupils exclude the optic tract.', 'No neglect or numbness argues against the parietal lobe.'],
  w: 'Defects are more alike in the two eyes the further back the lesion, and the central field at the occipital pole often has a double blood supply, so it may be spared.',
  st: ['The same half is missing in both eyes, behind the chiasm.', 'The defects match closely with central sparing.', 'That points to the occipital cortex.'],
  p: 'An isolated matching hemianopia suggests a posterior cerebral artery stroke.', g: ['field-defects', 'vision']},
 'case-074': {ti: 'Blind with normal pupils', k: 'Localize',
  s: 'A 75-year-old woman woke unable to see anything, though she insists she can. Her eyes look normal.',
  f: ['Both pupils react briskly to light', 'Eye movements are full', 'A scan shows strokes in both occipital lobes'],
  q: 'What explains the blindness?',
  o: ['Damage to the visual cortex on both sides', 'Damage to both optic nerves', 'Failure of both retinas', 'Damage to both optic tracts'],
  r: ['Best fit. Blindness with brisk pupils and occipital strokes is cortical blindness; denial of blindness (Anton syndrome) can occur.', 'Optic nerve damage would weaken the pupil response.', 'Retinal failure would weaken the pupil response and show on examination.', 'Optic tract damage would affect the pupils.'],
  fn: ['Brisk pupils show the eyes, nerves and tracts work.', 'Full eye movements exclude a brainstem cause.', 'Bilateral occipital strokes explain the loss.'],
  w: 'The pupil reflex leaves the visual pathway before the visual cortex, so cortical blindness keeps normal pupils.',
  st: ['She cannot see.', 'Her pupils react normally.', 'So the problem is behind the pupil pathway: the visual cortex.'],
  p: 'Blindness with normal pupils points to the visual cortex.', g: ['vision', 'pupil-reflex']},
 'case-075': {ti: 'Straight lines look bent', k: 'Localize',
  s: 'A 68-year-old man notices that door frames look wavy when he looks with his right eye. His left eye is fine.',
  f: ['There is no pupil defect', 'Moving the eye is not painful', 'A scan of the back of the eye shows a change at the centre of the retina'],
  q: 'Where is the problem?',
  o: ['Right macula (centre of the retina)', 'Right optic nerve', 'Left optic tract', 'Occipital lobe'],
  r: ['Best fit. Wavy lines in one eye with normal pupils and a central retinal change point to the macula, as in macular degeneration.', 'Optic nerve disease reduces colour and causes a pupil defect.', 'An optic tract lesion affects both eyes.', 'Occipital lesions affect both eyes.'],
  fn: ['No pupil defect makes optic nerve disease unlikely.', 'No pain on movement argues against optic neuritis.', 'A central retinal change explains distortion.'],
  w: 'Distortion of lines in one eye comes from displaced photoreceptors at the macula.',
  st: ['The problem is in one eye.', 'Pupils are normal.', 'A macular change explains the distortion.'],
  p: 'Wavy lines in one eye suggest a macular problem; refer to an eye specialist.', g: ['field-defects']},
 'case-076': {ti: 'Unsteady walking: which kind?', k: 'Discriminate',
  s: 'A 64-year-old woman walks unsteadily. You want to know whether loss of position sense is causing it.',
  f: ['There is no major weakness', 'The history alone does not settle it', 'You can test both sensation and coordination'],
  q: 'Which finding best supports sensory ataxia?',
  o: ['Poor toe position sense and fingers that drift when she closes her eyes', 'Overshooting the target with eyes open and normal position sense', 'Jerky eye movements and nystagmus', 'Swaying while sitting with eyes open'],
  r: ['Best fit. Poor position sense with drifting, searching fingers when the eyes close (pseudoathetosis) is sensory ataxia.', 'Overshoot with normal position sense is cerebellar.', 'Nystagmus and jerky pursuit are cerebellar or brainstem signs.', 'Sway while seated with eyes open is a midline cerebellar sign.'],
  fn: ['No weakness keeps the problem in coordination or sensation.', 'History alone is not enough.', 'A specific bedside sign decides.'],
  w: 'Sensory ataxia comes from lost position sense, so it worsens with the eyes closed and is accompanied by poor joint position testing.',
  st: ['Both sensory and cerebellar problems cause unsteadiness.', 'Sensory ataxia needs lost position sense.', 'Test position sense and look for drift with eyes closed.'],
  p: 'Always test position sense before calling ataxia cerebellar.', g: ['coordination', 'sensory-pathways']},
 'case-077': {ti: 'Vision jumps when the head turns', k: 'Localize',
  s: 'A 72-year-old man complains that things jump about. You see his eyes drift up and flick down repeatedly when he looks straight ahead.',
  f: ['His position sense is normal', 'No single eye muscle is weak', 'His limbs are only slightly clumsy', 'He cannot keep his eyes on a target that moves with his head'],
  q: 'Which part of the cerebellum is affected?',
  o: ['Flocculus (eye stability region)', 'Midline vermis for gait', 'Lateral hemisphere for the limbs', 'Front of the vermis'],
  r: ['Best fit. Downbeat nystagmus, broken pursuit and failure to cancel the vestibular reflex point to the flocculus.', 'The midline vermis mainly affects gait and saccade accuracy.', 'The lateral hemispheres mainly affect limb coordination.', 'The front of the vermis mainly causes gait ataxia.'],
  fn: ['Normal position sense excludes sensory ataxia.', 'No muscle weakness keeps the problem in eye movement control.', 'Mild limb clumsiness suggests the limbs are relatively spared.', 'Failure to follow a target moving with the head is failed reflex cancellation.'],
  w: 'The flocculus keeps the eyes steady, supports smooth pursuit and cancels the vestibular reflex when needed. Damage causes downbeat nystagmus.',
  st: ['The eyes drift and flick down: downbeat nystagmus.', 'Pursuit and reflex cancellation fail.', 'Those are flocculus functions.'],
  p: 'Downbeat nystagmus points to the cerebellum or the junction of the brainstem and spinal cord.', g: ['coordination', 'gaze-circuit']},
 'case-078': {ti: 'Eyes overshoot the target', k: 'Predict',
  s: 'A small stroke involves the midline vermis and the nearby deep cerebellar (fastigial) nucleus in a 63-year-old man.',
  f: ['Acuity and visual fields are normal', 'Each eye moves fully in every direction', 'No eye nerve is weak'],
  q: 'Which eye movement problem do you expect?',
  o: ['Quick eye jumps that overshoot or undershoot the target', 'One eye failing to move in on side gaze', 'One eye failing to move out', 'Pupils that react to near but not light'],
  r: ['Best fit. The vermis and fastigial nucleus set the size of quick eye jumps (saccades); damage makes them overshoot or undershoot.', 'Failure to move in on side gaze is an MLF sign.', 'Failure to move out is a sixth nerve problem.', 'Light–near dissociation is a dorsal midbrain sign.'],
  fn: ['Normal vision excludes a visual cause.', 'A full range excludes eye muscle weakness.', 'No nerve palsy keeps the problem central.'],
  w: 'The dorsal vermis and fastigial nucleus calibrate saccade size. Damage causes saccadic dysmetria.',
  st: ['The lesion is in the midline cerebellum.', 'This region calibrates saccades.', 'Expect overshooting saccades.'],
  p: 'Watch saccades between two targets; overshoot suggests the midline cerebellum.', g: ['coordination']},
 'case-079': {ti: 'The world bounces when walking', k: 'Localize',
  s: 'A 57-year-old woman was treated with gentamicin for a serious infection. Now the world bounces when she walks and she staggers in the dark, but she feels fine sitting still.',
  f: ['When you turn her head quickly either way, her eyes lag and then catch up', 'Specialist tests confirm weak balance organs on both sides', 'Position sense, limb coordination and eye tracking are normal'],
  q: 'Which system is affected?',
  o: ['Both inner-ear balance organs', 'One inner-ear balance organ', 'Back of the spinal cord', 'Cerebellar hemispheres'],
  r: ['Best fit. Bouncing vision on walking, unsteadiness in the dark and abnormal head impulses on both sides point to bilateral vestibular loss, a known effect of gentamicin.', 'One-sided loss causes vertigo and an abnormal head impulse on one side only.', 'Dorsal column disease reduces position sense.', 'Cerebellar disease causes limb clumsiness and abnormal eye tracking.'],
  fn: ['Lagging eyes on head turns to both sides show a weak vestibular reflex on both sides.', 'Testing confirms bilateral loss.', 'Normal sensation, coordination and tracking exclude other causes.'],
  w: 'The vestibular reflex keeps vision stable when the head moves. Without it on both sides, vision bounces with walking and balance depends on sight.',
  st: ['Vision bounces with head movement.', 'Head impulses are abnormal both ways.', 'That is bilateral vestibular loss.'],
  p: 'Ask about bouncing vision after gentamicin.', g: ['coordination']},
 'case-080': {ti: 'Reaching wrongly for things she can see', k: 'Localize',
  s: 'A 65-year-old woman reaches past cups and doorknobs she is looking at, but can touch her own nose perfectly with her eyes closed. She says she can only see one thing at a time.',
  f: ['Strength and position sense are normal', 'She cannot describe a whole picture, only one item in it', 'Acuity and eye movement range are normal'],
  q: 'Where is the lesion?',
  o: ['Both parietal lobes (back of the brain)', 'Cerebellum on both sides', 'Both occipital lobes', 'Both temporal lobes'],
  r: ['Best fit. Misreaching for seen objects with normal reaching by body sense, and seeing only one thing at a time, point to both posterior parietal lobes (Bálint syndrome).', 'Cerebellar ataxia would also spoil touching her nose.', 'Occipital damage reduces vision itself.', 'Temporal damage impairs recognising objects rather than reaching.'],
  fn: ['Normal strength and position sense exclude motor and sensory causes.', 'Seeing one item at a time is simultanagnosia.', 'Normal acuity and eye movements show the eyes work.'],
  w: 'The posterior parietal lobes link vision to action and attention. Damage on both sides causes optic ataxia and simultanagnosia.',
  st: ['She sees but reaches wrongly.', 'Reaching by body sense is fine.', 'That points to the posterior parietal lobes.'],
  p: 'Ask the person to describe a busy picture; simultanagnosia is easy to miss.', g: ['cortex', 'vision']},
 'case-081': {ti: 'Clumsy hands and stiff legs at 62', k: 'Localize',
  s: 'A 62-year-old man has found buttons hard for five months and now his legs feel stiff on stairs.',
  f: ['His hand muscles are thin; his ankle reflexes are brisk and his toes go up', 'He has a level of reduced pinprick on his upper chest; his face and jaw reflex are normal'],
  q: 'Where is the lesion?',
  o: ['Cervical spinal cord', 'Nerve roots in the neck only', 'Both brachial plexuses', 'Motor neuron disease'],
  r: ['Best fit. Lower motor neuron hand signs, upper motor neuron leg signs and a chest sensory level point to the cervical cord.', 'Root lesions cannot cause brisk legs.', 'Plexus lesions do not affect the legs.', 'Motor neuron disease does not cause a sensory level, and the normal jaw reflex argues against it.'],
  fn: ['Thin hands are lower motor neuron signs; brisk legs and upgoing toes are upper motor neuron signs.', 'A chest level with a normal face and jaw reflex confirms the cervical cord.'],
  w: 'A cervical cord lesion damages hand motor neurons at its level and the leg tracts passing through it.',
  st: ['Hands show lower, legs upper motor neuron signs.', 'There is a sensory level.', 'That is the cervical cord.'],
  p: 'A normal jaw reflex with brisk limbs favours the cervical cord over a brain or brainstem cause.', g: ['cord-syndromes', 'umn-lmn']},
 'case-082': {ti: 'One leg stiff after an injury', k: 'Predict',
  s: 'After a fall, a 40-year-old woman\'s right leg is stiff and she cannot tell the position of her right toes. Her arms are normal. A scan shows damage mainly to the right side of the thoracic cord.',
  f: ['Her right leg is stiff and weak with brisk reflexes', 'She cannot feel the position or vibration of her right toes'],
  q: 'What do you expect to find?',
  o: ['Reduced pain and temperature in the left leg', 'Reduced pain and temperature in the right leg', 'Reduced vibration in the left leg', 'Reduced pain in the right arm'],
  r: ['Best fit. Pain fibres cross soon after entering the cord, so a right-sided lesion reduces pain and temperature in the left leg.', 'Right leg pain fibres travel on the left, so they are spared.', 'Left leg vibration fibres travel on the left, so they are spared.', 'A thoracic lesion cannot affect the arm.'],
  fn: ['Upper motor neuron weakness in the right leg places the damage at or above the cord on the right.', 'Position and vibration travel up the same side of the cord, so their loss on the right confirms a right-sided cord lesion.'],
  w: 'At one level, the spinothalamic tract carries pain from the opposite side of the body.',
  st: ['The lesion is right-sided.', 'Pain fibres from the left leg ascend on the right.', 'So the left leg loses pain sensation.'],
  p: 'In a hemicord lesion, look for pain loss in the leg that is not weak.', g: ['hemicord', 'sensory-pathways']},
 'case-083': {ti: 'Unsteady in the dark: cord or nerves?', k: 'Discriminate',
  s: 'A 45-year-old man is very unsteady in the dark. Toe position sense is poor, but strength and pinprick are normal.',
  f: ['Toe position and vibration are poor in both feet', 'Closing his eyes makes him much less steady'],
  q: 'Which finding would point to the spinal cord?',
  o: ['A clear sensory level on the trunk', 'More sway with eyes closed', 'Poor detection of big-toe movement', 'Walking better while watching his feet'],
  r: ['Best fit. A sensory level on the trunk only occurs with a cord lesion.', 'More sway with eyes closed happens with both.', 'Poor toe position happens with both.', 'Better walking with vision happens with both.'],
  fn: ['Loss of position and vibration sense means the large sensory fibres or the back of the cord are failing.', 'Romberg sign: he relies on his eyes because position sense from the feet is lost.'],
  w: 'Dorsal column disease and large-fibre neuropathy both remove position sense. Only a cord lesion creates a level on the trunk.',
  st: ['Both sites cause the same unsteadiness.', 'A trunk level is specific to the cord.', 'Look for it.'],
  p: 'Search the trunk for a sensory level in every unexplained sensory ataxia.', g: ['sensory-pathways', 'cord-syndromes']},
 'case-084': {ti: 'Floppy legs right after an injury', k: 'Localize',
  s: 'A 29-year-old woman fell from a horse an hour ago. Her legs are completely floppy with no reflexes.',
  f: ['Pinprick is lost below a clear line on the middle of her chest', 'She cannot pass urine; her arms are normal'],
  q: 'Where is the lesion?',
  o: ['Thoracic spinal cord (spinal shock)', 'Lumbar and sacral nerve roots', 'Peripheral nerves of both legs', 'Both sacral plexuses'],
  r: ['Best fit. A clear chest level and urinary retention after injury point to the thoracic cord; floppy legs with no reflexes are early spinal shock.', 'Root lesions do not give a chest level.', 'A neuropathy does not cause a sharp chest level or come on with injury.', 'Plexus lesions do not cause a chest level or bladder failure.'],
  fn: ['A chest sensory level means the cord.', 'Urinary retention with normal arms fits a thoracic cord lesion.'],
  w: 'Right after a severe cord injury, reflexes and tone below the lesion can disappear (spinal shock). Brisk reflexes appear later.',
  st: ['There is a sensory level on the chest.', 'The bladder is affected.', 'Despite floppy legs, it is the cord.'],
  p: 'Floppy legs with a sensory level after injury are still a cord lesion.', g: ['cord-syndromes', 'umn-lmn']},
 'case-085': {ti: 'Numb saddle and mixed reflexes', k: 'Localize',
  s: 'A 51-year-old man developed numbness around his back passage, trouble passing urine and weak legs over a few days.',
  f: ['His ankle reflexes are reduced but his knees are brisk and his toes go up', 'Saddle numbness is equal on both sides; his arms are normal'],
  q: 'Where is the lesion?',
  o: ['Lowest part of the spinal cord (conus)', 'Cauda equina roots only', 'Both lumbar plexuses', 'Both sciatic nerves'],
  r: ['Best fit. Mixed upper and lower motor neuron signs with symmetric saddle numbness and bladder problems point to the conus.', 'Cauda equina lesions cause only lower motor neuron signs.', 'Plexus lesions do not cause saddle numbness or upgoing toes.', 'Sciatic lesions do not cause saddle or bladder problems.'],
  fn: ['Brisk knees and upgoing toes with low ankle reflexes mix upper and lower motor neuron signs.', 'Symmetric saddle numbness fits the conus.'],
  w: 'The conus contains the lowest cord segments and the roots leaving them, so a lesion here can mix both types of sign.',
  st: ['Upper and lower motor neuron signs are mixed.', 'The saddle and bladder are involved symmetrically.', 'That fits the conus.'],
  p: 'Mixed reflexes in the legs with saddle loss suggest the conus.', g: ['conus-cauda', 'umn-lmn']},
 'case-086': {ti: 'Several roots or the plexus?', k: 'Discriminate',
  s: 'A 56-year-old woman with diabetes has six weeks of painful, uneven weakness in her legs, saddle numbness and reduced ankle reflexes.',
  f: ['There is no sensory level and the toes go down', 'The weakness involves hip, knee and ankle muscles on both sides, worse on the left'],
  q: 'Which finding would favour the roots?',
  o: ['Back pain made worse by coughing, straining or bending', 'Numbness on the outer foot only', 'Weakness limited to the calf and foot', 'A reduced ankle reflex on the weaker side'],
  r: ['Best fit. Pain made worse by coughing, straining or bending comes from structures inside the spinal canal, which favours the roots; saddle loss on both sides also fits roots better than a one-sided plexus.', 'Outer foot numbness can come from either.', 'Distal-only weakness suggests a distal nerve process.', 'A reduced ankle reflex occurs with both.'],
  fn: ['No sensory level and downgoing toes exclude the cord.', 'Weakness across many muscles in both legs could come from several roots or from the lumbosacral plexus.'],
  w: 'Roots lie inside the spinal canal, so pain worsened by coughing, straining or bending, and saddle involvement, point to them; plexus lesions lie outside the canal.',
  st: ['The cord is excluded.', 'Root and plexus can look similar.', 'Spinal pain features and saddle loss favour roots.'],
  p: 'Ask whether coughing or straining makes the pain worse.', g: ['conus-cauda', 'lumbosacral']},
 'case-087': {ti: 'Painless burns on both forearms', k: 'Localize',
  s: 'A 34-year-old man keeps finding painless burns on his forearms and hands from hot water.',
  f: ['Pain and temperature are lost over several bands in both arms', 'Vibration and finger position are normal; his trunk and legs feel normal'],
  q: 'Where is the lesion?',
  o: ['Centre of the cervical spinal cord', 'Back of the cervical cord', 'One side of the cervical cord', 'Several cervical nerve roots'],
  r: ['Best fit. Pain and temperature loss in both arms with vibration spared and normal legs points to the centre of the cervical cord, as with a syrinx.', 'Dorsal column lesions remove vibration.', 'A one-sided lesion would cause loss below a level on one side.', 'Root lesions remove all sensations in their bands.'],
  fn: ['Pain loss over several arm bands on both sides is a segmental pattern.', 'Spared vibration and normal legs show only crossing fibres in a few segments are affected.'],
  w: 'Pain fibres cross in front of the central canal. A central lesion cuts these on both sides at those levels.',
  st: ['Pain and temperature are lost in both arms.', 'Vibration and the legs are spared.', 'That is the centre of the cervical cord.'],
  p: 'Painless burns suggest a syrinx; check for wasting in the hands too.', g: ['cord-syndromes', 'sensory-pathways']},
 'case-088': {ti: 'Numb hands: just nerves?', k: 'Discriminate',
  s: 'A 70-year-old man has numb hands and trouble with keys. Both median and ulnar hand muscles are weak on both sides.',
  f: ['The numbness covers the whole of both hands, not one nerve territory', 'He has no neck pain and the arm reflexes are hard to judge'],
  q: 'Which examination best checks for a spinal cord problem as well?',
  o: ['Leg tone, plantar responses and walking', 'Thumb and finger strength again', 'Fingertip sensation again', 'Arm reflexes only'],
  r: ['Best fit. Upper motor neuron signs in the legs (stiffness, upgoing toes, stiff gait) would reveal a cervical cord problem.', 'Repeating hand strength does not test the cord.', 'Repeating fingertip sensation does not test the cord.', 'Arm reflexes alone can be changed by roots or cord.'],
  fn: ['A glove-like pattern in both hands does not follow one nerve, so a more central cause is possible.', 'Without clear arm signs, the hands alone cannot separate nerves from the cervical cord.'],
  w: 'Cervical cord compression can mimic nerve problems in the hands. Leg signs reveal it.',
  st: ['The hands do not fit one nerve.', 'The cervical cord can cause this.', 'Look for upper motor neuron signs in the legs.'],
  p: 'In bilateral hand numbness, always examine the legs.', g: ['cord-syndromes', 'umn-lmn']},
 'case-089': {ti: 'Unsteady on rough ground', k: 'Localize',
  s: 'A 78-year-old woman has had numb feet for a year and now feels unsteady on grass and uneven ground.',
  f: ['Vibration and toe position are reduced at the feet; ankle reflexes are absent', 'Nerve tests show reduced sensory signals in both legs', 'There is no sensory level and the toes go down'],
  q: 'Where is the problem?',
  o: ['Large sensory nerve fibres (neuropathy)', 'Back of the spinal cord', 'Cerebellum', 'Small sensory nerve fibres'],
  r: ['Best fit. Distal loss of vibration and position with absent ankle reflexes and reduced sensory nerve signals is a large-fibre neuropathy.', 'Dorsal column disease spares the ankle reflexes and nerve tests.', 'Cerebellar disease does not cause sensory loss.', 'Small fibres carry pain and temperature, not vibration or reflexes.'],
  fn: ['Distal vibration and position loss with absent ankle reflexes points to large fibres.', 'Reduced sensory nerve signals place the problem in the nerves.', 'No level or upgoing toe excludes the cord.'],
  w: 'Large nerve fibres carry vibration, position and the sensory part of the reflex arc.',
  st: ['Position sense is lost at the feet.', 'Ankle reflexes are gone.', 'That is a large-fibre neuropathy.'],
  p: 'Unsteadiness on uneven ground can be the first sign of a neuropathy.', g: ['body-patterns', 'sensory-pathways']},
 'case-090': {ti: 'Numb hands before feet', k: 'Localize',
  s: 'A 48-year-old woman developed patchy numbness in her left hand, then her right arm and one foot over eight months. Her fingers move clumsily when she cannot see them.',
  f: ['Position sense is badly reduced in the hands; strength is normal', 'Nerve tests show very low sensory signals in the arms, with normal motor signals', 'There is no level on the trunk'],
  q: 'Where is the problem?',
  o: ['Sensory nerve cells in the dorsal root ganglia', 'Length-dependent neuropathy', 'Nerve roots before the ganglia', 'Back of the spinal cord'],
  r: ['Best fit. Patchy, hands-first sensory loss with very low sensory signals and normal strength is a sensory ganglionopathy.', 'A length-dependent neuropathy starts in the feet and is symmetric.', 'Lesions before the ganglia keep sensory signals normal.', 'Dorsal column disease keeps sensory nerve signals normal.'],
  fn: ['Severe position loss with normal strength is pure sensory ataxia.', 'Low sensory but normal motor signals point to the sensory nerve cells.', 'No trunk level excludes the cord.'],
  w: 'A ganglionopathy damages the sensory nerve cell bodies themselves, so it is not length-dependent and can start in the hands or be patchy.',
  st: ['Sensory loss starts in the hands, patchy.', 'Sensory signals are very low.', 'That is the sensory ganglia.'],
  p: 'Hands-first, patchy sensory ataxia suggests a ganglionopathy, which can be linked to cancer or autoimmune disease.', g: ['sensory-pathways', 'body-patterns']},
 'case-091': {ti: 'Neck pain to the thumb', k: 'Localize',
  s: 'A 39-year-old man has had pain from his neck to his thumb for four weeks. Looking up makes it worse.',
  f: ['Bending the elbow and lifting the wrist are weak; the brachioradialis reflex is reduced', 'The thumb and outer forearm are numb'],
  q: 'Where is the lesion?',
  o: ['C6 nerve root', 'Radial nerve', 'Musculocutaneous nerve', 'C8 nerve root'],
  r: ['Best fit. Weak elbow flexion and wrist extension (two nerves sharing C6), a reduced brachioradialis reflex and thumb numbness with neck pain point to C6.', 'The radial nerve does not bend the elbow through the biceps.', 'The musculocutaneous nerve does not lift the wrist.', 'C8 affects the hand and little finger.'],
  fn: ['Weak elbow flexion and wrist extension share C6.', 'Thumb and forearm numbness follows the C6 dermatome.'],
  w: 'C6 supplies the elbow flexors and wrist extensors through different nerves and carries the brachioradialis reflex.',
  st: ['Neck pain worse with movement suggests a root.', 'The weak muscles use two nerves but share C6.', 'The reflex and thumb confirm C6.'],
  p: 'Thumb numbness with neck pain points to C6.', g: ['root-signatures', 'dermatome-landmarks']},
 'case-092': {ti: 'Root or radial nerve?', k: 'Discriminate',
  s: 'A 43-year-old man has weak elbow and finger straightening and a reduced triceps reflex.',
  f: ['Pain runs from the neck down the back of the arm', 'Numbness on the back of the hand is vague and hard to map'],
  q: 'Which strength test looks beyond the radial nerve?',
  o: ['Turning the palm down against resistance', 'Straightening the fingers', 'Straightening the elbow', 'Lifting the wrist'],
  r: ['Best fit. Turning the palm down (pronator teres) uses C7 through the median nerve, so its weakness points to the root.', 'Finger straightening is radial.', 'Elbow straightening (triceps) is radial.', 'Wrist lifting is radial.'],
  fn: ['Neck pain into the arm hints at a root, but nerve pain can spread too.', 'The sensory map cannot separate the radial nerve from C7.'],
  w: 'To separate a root from a nerve, test a muscle with the same root but a different nerve.',
  st: ['Both C7 and the radial nerve fit so far.', 'Find a C7 muscle outside the radial nerve.', 'Pronation (median, C6–C7) does that.'],
  p: 'Pronation is a useful C7 check outside the radial nerve.', g: ['root-signatures', 'brachial-plexus']}
});
Object.assign(window.NL_CASES_V2, {
 'case-093': {ti: 'A pianist\'s weak little finger', k: 'Discriminate',
  s: 'A 30-year-old pianist has weak finger spreading and tingling in her ring and little fingers for two months.',
  f: ['The small hand muscles that spread the fingers are thin', 'Tingling covers the little finger and half of the ring finger'],
  q: 'Which weakness would argue against an ulnar nerve lesion alone?',
  o: ['Weak thumb abduction (lifting the thumb off the palm)', 'Weak little-finger abduction', 'Weak index-finger spreading', 'Weak thumb adduction (pinch)'],
  r: ['Best fit. Thumb abduction (abductor pollicis brevis) is C8–T1 but supplied by the median nerve, so its weakness points beyond the ulnar nerve.', 'Little-finger abduction is ulnar.', 'Index finger spreading (first dorsal interosseous) is ulnar.', 'Thumb adduction (adductor pollicis) is ulnar.'],
  fn: ['Finger-spreading muscles are supplied by the ulnar nerve and by C8–T1.', 'This sensory area fits the ulnar nerve but also overlaps C8.'],
  w: 'Abductor pollicis brevis shares C8–T1 with the ulnar hand muscles but uses the median nerve.',
  st: ['Ulnar and C8–T1 lesions overlap in the hand.', 'Find a C8–T1 muscle outside the ulnar nerve.', 'Thumb abduction is median-supplied.'],
  p: 'Test thumb abduction in every ulnar-looking hand problem.', g: ['hand-nerves', 'brachial-plexus']},
 'case-094': {ti: 'A knee that gives way', k: 'Localize',
  s: 'A 57-year-old man has six weeks of back pain spreading into the front of his thigh and now struggles to climb steps.',
  f: ['Straightening the knee and bringing the thigh inward are weak; the knee reflex is reduced', 'The pain is worse when he coughs or bends'],
  q: 'Where is the lesion?',
  o: ['L3–L4 nerve roots', 'Femoral nerve', 'Obturator nerve', 'L5 nerve root'],
  r: ['Best fit. Weak knee extension (femoral) and hip adduction (obturator), which share L3–L4, with a reduced knee reflex and back pain worse on coughing point to the roots.', 'The femoral nerve does not bring the thigh inward.', 'The obturator nerve does not straighten the knee.', 'L5 affects foot lifting and hip abduction.'],
  fn: ['Weak knee extension and hip adduction use two nerves but share L3–L4.', 'Pain worse on coughing points to the spinal canal.'],
  w: 'The femoral and obturator nerves both arise from L2–L4. Weakness in both territories points to the roots.',
  st: ['Two nerves are involved.', 'They share L3–L4.', 'Spinal pain features point to the roots.'],
  p: 'Test hip adduction whenever the knee is weak.', g: ['lumbosacral', 'root-signatures']},
 'case-095': {ti: 'Foot drop: which test next?', k: 'Discriminate',
  s: 'A 36-year-old man has had foot drop for a few weeks after lateral leg pain.',
  f: ['Lifting the foot and toes is weak', 'The top of the foot is numb and there is no back pain'],
  q: 'Which test best looks outside the fibular nerve?',
  o: ['Moving the leg out to the side (hip abduction)', 'Lifting the big toe', 'Turning the foot outward', 'Comparing feeling in the first web space'],
  r: ['Best fit. Hip abduction (gluteus medius) uses L5 through the superior gluteal nerve, so weakness points to the root.', 'Big toe lifting is fibular.', 'Turning the foot outward is fibular.', 'First web space sensation is fibular.'],
  fn: ['Foot drop can come from the L5 root or the common fibular nerve.', 'Numbness over the top of the foot fits both L5 and the fibular nerve.'],
  w: 'L5 also supplies hip abduction through the superior gluteal nerve.',
  st: ['Both lesions cause foot drop.', 'Find an L5 muscle outside the fibular nerve.', 'Test hip abduction.'],
  p: 'Hip abduction and foot inversion separate L5 from a fibular palsy.', g: ['lumbosacral']},
 'case-096': {ti: 'Weak push-off with back pain', k: 'Localize',
  s: 'A 46-year-old woman has five weeks of pain from her back down the back of her leg and cannot push off when walking.',
  f: ['Pushing the foot down, bending the knee and squeezing the buttock are weak; the ankle reflex is reduced', 'Lifting the toes is normal and the pain is worse when she coughs'],
  q: 'Where is the lesion?',
  o: ['S1 nerve root', 'Tibial nerve', 'Sciatic nerve', 'L4 nerve root'],
  r: ['Best fit. Weakness of the calf, hamstrings and buttock (three nerves sharing S1), a reduced ankle reflex and pain worse on coughing point to S1.', 'The tibial nerve does not supply the buttock or hamstrings.', 'The sciatic nerve does not supply the buttock (gluteus maximus).', 'L4 affects knee extension and the knee reflex.'],
  fn: ['Calf, hamstring and buttock weakness share S1 but use different nerves.', 'Normal toe lifting spares L5; pain on coughing points to the canal.'],
  w: 'Gluteus maximus is supplied by the inferior gluteal nerve, not the sciatic nerve, so its weakness with calf weakness points to the root.',
  st: ['Several nerves are weak.', 'They share S1.', 'Spinal pain features confirm the root.'],
  p: 'Check buttock strength to separate S1 from a sciatic nerve lesion.', g: ['root-signatures', 'lumbosacral']},
 'case-097': {ti: 'Shoulder weakness after a traction injury', k: 'Localize',
  s: 'Six weeks after being pulled by the arm in a rugby tackle, a 24-year-old cannot lift his arm out to the side or bend his elbow strongly.',
  f: ['Shoulder abduction, outward rotation and elbow flexion are weak; the hand is normal', 'The outer forearm is numb; his shoulder blade does not wing and the rhomboids are strong'],
  q: 'Where is the lesion?',
  o: ['Upper trunk of the brachial plexus', 'C5–C6 nerve roots', 'Axillary nerve', 'Musculocutaneous nerve'],
  r: ['Best fit. Weakness in muscles of three nerves sharing C5–C6, with the nerves that leave at the roots (to the serratus and rhomboids) spared, points to the upper trunk.', 'A root lesion would usually weaken the serratus anterior or rhomboids.', 'The axillary nerve does not bend the elbow.', 'The musculocutaneous nerve does not lift the shoulder.'],
  fn: ['Shoulder and elbow weakness across several nerves shares C5–C6.', 'Spared serratus and rhomboids place the lesion beyond the roots.'],
  w: 'Nerves to the serratus anterior and rhomboids leave right at the C5–C7 roots. When they are spared, the lesion is further out, in the upper trunk.',
  st: ['Several C5–C6 nerves are weak.', 'The nerves leaving at the roots are spared.', 'So the upper trunk.'],
  p: 'Check for scapular winging to tell root from upper trunk injury.', g: ['brachial-plexus']},
 'case-098': {ti: 'Weak hand and numb inner forearm', k: 'Localize',
  s: 'A 60-year-old woman who had radiotherapy for breast cancer develops a weak left hand and a numb inner forearm.',
  f: ['Thumb abduction and finger spreading are weak', 'The inner forearm and little-finger side of the hand are numb', 'Her shoulder and elbow are strong and there is no neck pain'],
  q: 'Where is the lesion?',
  o: ['Lower brachial plexus', 'Ulnar nerve at the elbow', 'Median nerve in the forearm', 'C8 nerve root'],
  r: ['Best fit. Median and ulnar hand weakness (both C8–T1) with inner forearm numbness after radiotherapy and no neck pain points to the lower plexus.', 'An ulnar lesion spares thumb abduction and the inner forearm.', 'A median lesion spares finger spreading.', 'A root lesion usually causes neck pain.'],
  fn: ['Weak thumb abduction (median) and finger spreading (ulnar) share C8–T1.', 'Inner forearm numbness is C8–T1 territory beyond the ulnar nerve.', 'No neck pain argues against the roots.'],
  w: 'The lower trunk carries C8–T1 fibres to median and ulnar hand muscles and the inner forearm skin. It can be damaged by radiotherapy or tumour.',
  st: ['Two nerves are weak, sharing C8–T1.', 'The inner forearm is numb.', 'Without neck pain, that is the lower plexus.'],
  p: 'Radiation and tumour are both causes of lower plexopathy; imaging helps.', g: ['brachial-plexus', 'hand-nerves']},
 'case-099': {ti: 'Cannot lift, straighten or extend', k: 'Localize',
  s: 'After a shoulder injury, a 32-year-old cannot lift his arm out to the side, straighten his elbow strongly or lift his wrist.',
  f: ['The deltoid, triceps and wrist extensors are weak', 'The biceps and outward rotation of the shoulder are strong; the back of the hand is numb'],
  q: 'Where is the lesion?',
  o: ['Posterior cord of the brachial plexus', 'Radial nerve', 'Axillary nerve', 'Upper trunk of the brachial plexus'],
  r: ['Best fit. Weakness of the deltoid (axillary nerve) and triceps and wrist extensors (radial nerve) points to the posterior cord, which gives rise to both.', 'A radial lesion spares the deltoid.', 'An axillary lesion spares the triceps and wrist.', 'An upper trunk lesion would weaken the biceps and outward rotation.'],
  fn: ['Deltoid, triceps and wrist extensors are the axillary and radial nerves.', 'Strong biceps and outward rotation spare the lateral cord and upper trunk.'],
  w: 'The posterior cord divides into the axillary and radial nerves.',
  st: ['Two nerves are weak: axillary and radial.', 'They come from the posterior cord.', 'Other cords are spared.'],
  p: 'Find the smallest structure all the weak muscles share.', g: ['brachial-plexus']},
 'case-100': {ti: 'Thigh weakness after pelvic surgery', k: 'Localize',
  s: 'A 67-year-old woman developed pain and weakness in her right thigh over weeks after pelvic surgery. She has no back pain.',
  f: ['Straightening the knee and bringing the thigh inward are weak', 'The front and inner thigh are numb', 'Coughing and bending do not change the pain'],
  q: 'Where is the lesion?',
  o: ['Lumbar plexus', 'Femoral nerve', 'Obturator nerve', 'L3–L4 nerve roots'],
  r: ['Best fit. Femoral and obturator weakness with front and inner thigh numbness, no back pain and a pelvic cause points to the lumbar plexus.', 'A femoral lesion spares hip adduction.', 'An obturator lesion spares knee extension.', 'Root lesions usually cause back pain worsened by coughing.'],
  fn: ['Two nerves are weak: femoral and obturator.', 'Numbness covers both territories.', 'No spinal pain features argue against the roots.'],
  w: 'The lumbar plexus gives rise to both the femoral and obturator nerves inside the pelvis.',
  st: ['Femoral and obturator territories are both involved.', 'There are no root features.', 'With a pelvic cause, that is the plexus.'],
  p: 'Pelvic surgery or bleeding can damage the lumbar plexus.', g: ['lumbosacral']},
 'case-101': {ti: 'Cannot make an "OK" sign', k: 'Predict',
  s: 'A 28-year-old man cannot make a round "OK" sign with his thumb and index finger after a forearm injury. The tips of the thumb and index finger will not bend.',
  f: ['Other median hand muscles are strong and thumb opposition is normal', 'The forearm turns the palm down a little weakly'],
  q: 'What will sensory testing show?',
  o: ['Normal feeling throughout the hand', 'Numb index fingertip', 'Numb base of the thumb', 'Numb first web space on the back of the hand'],
  r: ['Best fit. The anterior interosseous nerve is a purely motor branch of the median nerve, so feeling is normal.', 'Index fingertip numbness means the main median nerve.', 'Numbness at the base of the thumb means the palmar branch.', 'First web space numbness is the radial nerve.'],
  fn: ['Normal opposition and thenar strength spare the main median nerve at the wrist.', 'Weak pronation plus weak deep thumb and index flexors fits the anterior interosseous nerve.'],
  w: 'The anterior interosseous nerve supplies flexor pollicis longus, the index and middle deep flexors and pronator quadratus, and carries no skin sensation.',
  st: ['Only the deep thumb and index flexors are weak.', 'That is the anterior interosseous nerve.', 'It has no sensory supply.'],
  p: 'A pinch that collapses into a flat "OK" sign with normal feeling suggests anterior interosseous palsy.', g: ['hand-nerves']},
 'case-102': {ti: 'Fingers that will not straighten', k: 'Localize',
  s: 'A 54-year-old woman has had difficulty letting go of objects for three weeks. She can still lift her wrist, though it tilts toward the thumb.',
  f: ['The fingers and thumb cannot straighten; the wrist lifts with a tilt toward the thumb', 'The triceps is strong and feeling in the hand is normal'],
  q: 'Where is the lesion?',
  o: ['Posterior interosseous nerve', 'Radial nerve at the upper arm', 'C7 nerve root', 'Posterior cord of the brachial plexus'],
  r: ['Best fit. Finger drop with the wrist still lifting toward the thumb, a strong triceps and normal feeling point to the posterior interosseous nerve.', 'A radial lesion at the upper arm causes full wrist drop and numbness.', 'C7 would weaken the triceps.', 'A posterior cord lesion would weaken the deltoid and triceps.'],
  fn: ['Finger drop with a thumb-ward wrist tilt spares extensor carpi radialis longus.', 'A strong triceps and normal feeling spare the main radial nerve.'],
  w: 'The posterior interosseous nerve is a motor branch of the radial nerve. The main wrist extensor on the thumb side is supplied above it, so the wrist still lifts with a tilt.',
  st: ['The fingers drop, but the wrist lifts with a tilt.', 'Feeling and triceps are normal.', 'That is the posterior interosseous nerve.'],
  p: 'Finger drop with normal feeling suggests the posterior interosseous nerve.', g: ['hand-nerves']},
 'case-103': {ti: 'Median numbness and a weak forearm', k: 'Localize',
  s: 'A 41-year-old carpenter has numbness on the thumb side of his hand and struggles with a screwdriver.',
  f: ['Thumb opposition, bending the thumb tip and turning the palm down are weak', 'The index fingertip and the base of the thumb are numb', 'Ulnar hand muscles and wrist lifting are normal'],
  q: 'Where is the lesion?',
  o: ['Median nerve above the elbow or upper forearm', 'Median nerve at the wrist', 'Anterior interosseous nerve', 'C6 nerve root'],
  r: ['Best fit. Hand and forearm median muscles weak with numbness at the base of the thumb point to the median nerve above its forearm branches.', 'A wrist lesion spares forearm muscles and the base of the thumb.', 'The anterior interosseous nerve has no sensory supply.', 'C6 would affect elbow flexion and wrist lifting.'],
  fn: ['Weak hand and forearm median muscles place the lesion above the forearm branches.', 'Numb base of the thumb means the branch that leaves above the wrist.', 'Normal ulnar and radial muscles exclude the plexus.'],
  w: 'Pronator teres and the long thumb flexor are supplied in the forearm, and the palmar branch to the base of the thumb leaves above the wrist.',
  st: ['Forearm median muscles are weak.', 'The base of the thumb is numb.', 'So the lesion is above the forearm branches.'],
  p: 'Test pronation and thumb-tip flexion to tell a high median lesion from carpal tunnel syndrome.', g: ['hand-nerves']},
 'case-104': {ti: 'A cyclist\'s weak pinch', k: 'Localize',
  s: 'A 33-year-old cyclist after a long ride has a weak pinch between thumb and index finger and cannot spread his index finger.',
  f: ['Index finger spreading and thumb adduction are weak; little-finger spreading is normal', 'Forearm flexors are strong and feeling in the hand is normal'],
  q: 'Where is the lesion?',
  o: ['Deep motor branch of the ulnar nerve in the palm', 'Ulnar nerve at the elbow', 'Ulnar nerve sensory branch at the wrist', 'Lower brachial plexus'],
  r: ['Best fit. Weakness of the first dorsal interosseous and adductor pollicis with little-finger muscles spared and normal feeling points to the deep ulnar branch in the palm, compressed by handlebars.', 'An elbow lesion would cause numbness and weaken forearm muscles.', 'The sensory branch carries no motor fibres.', 'A plexus lesion would weaken median muscles and cause numbness.'],
  fn: ['Spared little-finger muscles place the lesion beyond their branches.', 'Normal feeling spares the sensory branches.'],
  w: 'In the palm, the deep ulnar branch supplies the little-finger muscles first, then the interossei and adductor pollicis. A lesion beyond the first branches spares the little-finger muscles and all sensation.',
  st: ['Only the index and thumb ulnar muscles are weak.', 'Feeling is normal.', 'That is the deep ulnar branch in the palm.'],
  p: 'Handlebar pressure can cause a purely motor ulnar palsy.', g: ['hand-nerves']},
 'case-105': {ti: 'Ulnar symptoms at the wrist', k: 'Predict',
  s: 'A 50-year-old cyclist has tingling in his ring and little fingers and weak hand muscles after long rides leaning on his handlebars.',
  f: ['The finger-spreading muscles are weak and the elbow is not tender', 'His symptoms started after long rides with pressure on the heel of the hand'],
  q: 'Which area should still feel normal?',
  o: ['The back of the hand on the little-finger side', 'The palm side of the little finger', 'The tip of the ring finger (little-finger side)', 'The pad of the little finger'],
  r: ['Best fit. The branch to the back of the hand leaves the ulnar nerve above the wrist, so it is spared in a wrist lesion.', 'The palm side of the little finger is supplied through the wrist.', 'The ring fingertip is supplied through the wrist.', 'The little-finger pad is supplied through the wrist.'],
  fn: ['Ulnar hand weakness with a normal elbow points lower down the nerve.', 'Pressure on the heel of the hand compresses the ulnar nerve at the wrist (Guyon canal).'],
  w: 'The dorsal ulnar cutaneous branch leaves several centimetres above the wrist.',
  st: ['The lesion is at the wrist.', 'The back-of-hand branch leaves above it.', 'So that area is spared.'],
  p: 'The back of the hand separates an elbow from a wrist ulnar lesion.', g: ['hand-nerves']},
 'case-106': {ti: 'Weak elbow bend after an injury', k: 'Localize',
  s: 'After an upper-arm injury, a 22-year-old has a weak elbow bend and cannot turn his palm up strongly.',
  f: ['The biceps is thin and its reflex is reduced', 'The outer forearm is numb; the shoulder muscles and brachioradialis are strong'],
  q: 'Where is the lesion?',
  o: ['Musculocutaneous nerve', 'C5–C6 nerve roots', 'Upper trunk of the brachial plexus', 'Radial nerve'],
  r: ['Best fit. Biceps weakness and wasting with outer forearm numbness and strong shoulder muscles and brachioradialis point to the musculocutaneous nerve.', 'A C5–C6 lesion would weaken the shoulder and brachioradialis.', 'An upper trunk lesion would weaken the shoulder.', 'The radial nerve supplies brachioradialis, which is strong.'],
  fn: ['A thin biceps with a reduced reflex is a lower motor neuron biceps lesion.', 'Outer forearm numbness with other C5–C6 muscles strong isolates one nerve.'],
  w: 'The musculocutaneous nerve supplies the biceps and brachialis and continues as the nerve to the outer forearm skin.',
  st: ['Only the biceps and outer forearm are affected.', 'Other C5–C6 muscles are strong.', 'That is the musculocutaneous nerve.'],
  p: 'Strong brachioradialis with weak biceps separates this nerve from C5–C6.', g: ['brachial-plexus']},
 'case-107': {ti: 'Weak shoulder after a dislocation', k: 'Localize',
  s: 'A 59-year-old woman dislocated her shoulder. It was put back, but she still cannot lift her arm out to the side.',
  f: ['The deltoid is weak and thin, and a patch over the outer shoulder is numb', 'Outward rotation by the infraspinatus and the biceps are strong', 'The triceps and wrist and finger extensors are strong'],
  q: 'Where is the lesion?',
  o: ['Axillary nerve', 'Suprascapular nerve', 'Upper trunk of the brachial plexus', 'Posterior cord of the brachial plexus'],
  r: ['Best fit. Deltoid weakness with numbness over the outer shoulder after a dislocation points to the axillary nerve.', 'The suprascapular nerve supplies the infraspinatus, which is strong.', 'An upper trunk lesion would weaken the biceps and infraspinatus.', 'A posterior cord lesion would weaken the radial muscles.'],
  fn: ['A thin deltoid with a numb outer shoulder patch is the axillary nerve.', 'Strong infraspinatus and biceps exclude the suprascapular nerve and upper trunk.', 'Strong radial muscles exclude the posterior cord.'],
  w: 'The axillary nerve wraps around the neck of the humerus and is easily stretched in shoulder dislocation.',
  st: ['Only the deltoid and its skin patch are affected.', 'Neighbouring nerves are spared.', 'That is the axillary nerve.'],
  p: 'Check the "regimental badge" patch of skin after every shoulder dislocation.', g: ['brachial-plexus']},
 'case-108': {ti: 'A shoulder blade that sticks out', k: 'Localize',
  s: 'A 26-year-old man has trouble pushing heavy doors after weeks of shoulder ache following gym work.',
  f: ['His shoulder blade sticks out along its inner edge when he pushes against a wall', 'Shrugging and pulling the shoulder blade back are strong; the arm feels normal'],
  q: 'Where is the lesion?',
  o: ['Long thoracic nerve', 'Accessory nerve (XI)', 'Dorsal scapular nerve', 'Suprascapular nerve'],
  r: ['Best fit. Inner-edge winging on pushing comes from serratus anterior weakness, supplied by the long thoracic nerve.', 'Accessory nerve palsy weakens the shrug and causes outer winging.', 'Dorsal scapular palsy weakens pulling the shoulder blade back.', 'Suprascapular palsy weakens lifting and outward rotation of the arm.'],
  fn: ['Inner-edge winging on pushing is serratus anterior weakness.', 'Normal shrug and retraction spare the trapezius and rhomboids.'],
  w: 'The serratus anterior holds the shoulder blade to the chest wall. Its nerve, the long thoracic nerve, is long and exposed.',
  st: ['The shoulder blade wings on pushing.', 'The trapezius and rhomboids are strong.', 'So the serratus anterior and its nerve.'],
  p: 'Ask the person to push against a wall to bring out winging.', g: ['brachial-plexus']},
 'case-109': {ti: 'A foot that rolls inward', k: 'Localize',
  s: 'After being kicked on the outer calf playing football, a 30-year-old finds his foot rolls inward when he walks.',
  f: ['Turning the foot outward is weak; lifting the foot and big toe is strong', 'Most of the top of the foot is numb, but the first web space feels normal'],
  q: 'Where is the lesion?',
  o: ['Superficial fibular nerve', 'Deep fibular nerve', 'Common fibular nerve', 'L5 nerve root'],
  r: ['Best fit. Weak eversion with strong foot lifting and numbness on the top of the foot sparing the first web space points to the superficial fibular branch.', 'The deep branch lifts the foot and supplies the first web space.', 'A common fibular lesion would weaken foot lifting too.', 'L5 would weaken foot lifting and inward turning.'],
  fn: ['Weak eversion with strong dorsiflexion isolates the superficial branch.', 'Top-of-foot numbness sparing the first web space fits the superficial branch.'],
  w: 'The common fibular nerve divides into a superficial branch (eversion and most of the top of the foot) and a deep branch (foot lifting and the first web space).',
  st: ['Only eversion is weak.', 'The first web space is spared.', 'That is the superficial fibular nerve.'],
  p: 'The first web space separates the deep from the superficial fibular branch.', g: ['lumbosacral']},
 'case-110': {ti: 'Foot drop with a numb web space', k: 'Localize',
  s: 'A 44-year-old woman hit the front of her shin and now cannot lift the front of her foot.',
  f: ['Lifting the foot and toes is weak; turning the foot in or out and hip abduction are normal', 'Numbness is limited to the web space between the first two toes'],
  q: 'Where is the lesion?',
  o: ['Deep fibular nerve in the leg', 'Deep fibular nerve at the ankle', 'Common fibular nerve', 'L5 nerve root'],
  r: ['Best fit. Weak foot and toe lifting with normal eversion and numbness only in the first web space points to the deep fibular nerve in the leg.', 'An ankle lesion would spare the muscles that lift the foot.', 'A common fibular lesion would weaken eversion.', 'L5 would weaken inward turning and hip abduction.'],
  fn: ['Weak lifting with normal eversion and inversion isolates the deep fibular branch.', 'First web space numbness is the deep fibular skin area.'],
  w: 'The deep fibular nerve supplies the muscles that lift the foot and only the skin of the first web space.',
  st: ['Only foot lifting is weak.', 'Only the first web space is numb.', 'That is the deep fibular nerve in the leg.'],
  p: 'Weak foot lifting with normal eversion points to the deep fibular nerve.', g: ['lumbosacral']},
 'case-111': {ti: 'Burning sole of the foot', k: 'Predict',
  s: 'A 53-year-old runner has numbness and burning in the sole of his foot and weak small foot muscles. Tapping behind the inner ankle sends tingling into the sole.',
  f: ['The sole and the small foot muscles are affected', 'The top of the foot feels normal'],
  q: 'Which finding fits a tarsal tunnel lesion?',
  o: ['Normal calf strength and a normal ankle reflex', 'Weak pushing off with an absent ankle reflex', 'Weak eversion with a numb top of the foot', 'Weak knee bending with a numb outer calf'],
  r: ['Best fit. The calf and ankle reflex are supplied above the ankle, so they stay normal in a tarsal tunnel lesion.', 'Calf weakness and a lost ankle reflex mean a lesion above the ankle.', 'Eversion weakness and top-of-foot numbness are fibular.', 'Knee bending weakness and calf numbness mean the sciatic nerve or roots.'],
  fn: ['The sole and small foot muscles are supplied by the tibial nerve branches beyond the ankle.', 'Normal feeling on the top of the foot spares the fibular nerve and L5.'],
  w: 'The tibial nerve supplies the calf above the ankle and divides into the plantar nerves in the tarsal tunnel.',
  st: ['The sole is affected.', 'A tarsal tunnel lesion is below the calf branches.', 'So calf strength and the ankle reflex are normal.'],
  p: 'Check the calf and ankle reflex before diagnosing tarsal tunnel syndrome.', g: ['lumbosacral']},
 'case-112': {ti: 'A knee that buckles after surgery', k: 'Localize',
  s: 'A 64-year-old woman\'s knee buckles when she stands after a pelvic operation.',
  f: ['Straightening the knee is weak and the knee reflex is reduced', 'Bringing the thigh inward is strong; the inner lower leg is numb', 'There is no back pain'],
  q: 'Where is the lesion?',
  o: ['Femoral nerve', 'Obturator nerve', 'L3–L4 nerve roots', 'Lumbar plexus'],
  r: ['Best fit. Weak knee extension, a reduced knee reflex and inner leg numbness with strong hip adduction point to the femoral nerve.', 'The obturator nerve brings the thigh inward, which is strong.', 'Root lesions would weaken hip adduction and cause back pain.', 'A plexus lesion would usually weaken hip adduction too.'],
  fn: ['Weak knee extension with a reduced knee reflex is the femoral nerve.', 'Strong hip adduction spares the obturator nerve.', 'No back pain argues against the roots.'],
  w: 'The femoral nerve supplies the quadriceps, carries the knee reflex and gives the saphenous branch to the inner leg.',
  st: ['Only the femoral territory is affected.', 'Hip adduction is normal.', 'So the femoral nerve.'],
  p: 'Test hip adduction to separate a femoral palsy from a root or plexus lesion.', g: ['lumbosacral']},
 'case-113': {ti: 'Cannot cross the legs', k: 'Localize',
  s: 'A 47-year-old woman cannot bring her right thigh inward to cross her legs after pelvic surgery.',
  f: ['The inner thigh muscles are weak and a small patch of inner thigh is numb', 'Straightening the knee, bending the hip and the knee reflex are normal'],
  q: 'Where is the lesion?',
  o: ['Obturator nerve', 'Femoral nerve', 'L2–L4 nerve roots', 'Lumbar plexus'],
  r: ['Best fit. Weak hip adduction with inner thigh numbness and a normal femoral territory points to the obturator nerve.', 'The femoral nerve straightens the knee, which is normal.', 'Root lesions would weaken the quadriceps too.', 'A plexus lesion would usually affect the femoral territory.'],
  fn: ['Weak inner thigh muscles with inner thigh numbness is the obturator nerve.', 'A normal femoral territory isolates it.'],
  w: 'The obturator nerve passes through the pelvis and supplies the thigh adductors and a patch of inner thigh skin.',
  st: ['Only hip adduction is weak.', 'The femoral territory is normal.', 'So the obturator nerve.'],
  p: 'Pelvic surgery can stretch the obturator nerve.', g: ['lumbosacral']},
 'case-114': {ti: 'Foot weakness after a hip injury', k: 'Localize',
  s: 'Six weeks after a hip fracture, a 37-year-old man has foot drop and also struggles to push off.',
  f: ['Lifting, turning in and out and pushing down the foot are all weak, and bending the knee is weak', 'Buttock and hip abduction strength are normal; the inner lower leg feels normal', 'The outer leg and sole are numb'],
  q: 'Where is the lesion?',
  o: ['Sciatic nerve in the thigh', 'Common fibular nerve', 'L5–S1 nerve roots', 'Sacral plexus'],
  r: ['Best fit. Weakness of fibular and tibial muscles and the hamstrings, with normal buttock and hip abduction, after a hip injury points to the sciatic nerve.', 'A fibular lesion spares pushing down, turning in and knee bending.', 'Root lesions would weaken the buttock and hip abduction.', 'A plexus lesion would usually weaken the buttock.'],
  fn: ['Fibular, tibial and hamstring weakness is the sciatic nerve.', 'Normal gluteal muscles place the lesion below the plexus.', 'Outer leg and sole numbness fits both divisions.'],
  w: 'The sciatic nerve carries both fibular and tibial fibres and supplies the hamstrings. The gluteal nerves leave separately above it.',
  st: ['Both divisions are weak.', 'The hamstrings are weak but the gluteals are not.', 'So the sciatic nerve.'],
  p: 'Hip fracture or surgery can injure the sciatic nerve; the fibular part is often worse.', g: ['lumbosacral']},
 'case-115': {ti: 'Burning feet with normal tests', k: 'Localize',
  s: 'A 42-year-old woman has had burning feet for months. Even bedsheets hurt. Her nerve conduction tests were normal.',
  f: ['Pinprick and temperature are reduced at the feet; vibration, position, strength and ankle reflexes are normal', 'Routine nerve conduction tests are normal'],
  q: 'Where is the problem?',
  o: ['Small sensory nerve fibres', 'Large sensory nerve fibres', 'Back of the spinal cord', 'Lumbar and sacral nerve roots'],
  r: ['Best fit. Burning pain with reduced pain and temperature but normal vibration, reflexes and conduction tests is a small-fibre neuropathy.', 'Large-fibre loss reduces vibration and reflexes.', 'Dorsal column disease reduces vibration and position.', 'Root lesions follow bands and usually cause back pain.'],
  fn: ['Pain and temperature loss with normal large-fibre functions points to small fibres.', 'Routine conduction tests measure large fibres, so they can be normal.'],
  w: 'Small fibres carry pain and temperature. Routine nerve tests do not measure them.',
  st: ['Only pain and temperature are lost.', 'Large-fibre tests are normal.', 'So small fibres.'],
  p: 'Normal nerve tests do not exclude a small-fibre neuropathy.', g: ['body-patterns']},
 'case-116': {ti: 'Wasting and twitching: motor only?', k: 'Discriminate',
  s: 'A 58-year-old man has slowly worsening wasting and twitching in one arm, with low reflexes.',
  f: ['Muscles in the hand and forearm are thin and twitch at rest', 'He has no pain and the reflexes in that arm are low'],
  q: 'Which finding would argue against a pure motor neuron problem?',
  o: ['Clear sensory loss in the same limb', 'Visible twitching in weak muscles', 'Low reflexes in the weak limb', 'Muscle wasting'],
  r: ['Best fit. Motor neurons carry no sensation, so clear sensory loss points to a root, plexus or nerve problem instead.', 'Twitching is typical of motor neuron disease.', 'Low reflexes fit lower motor neuron loss.', 'Wasting fits lower motor neuron loss.'],
  fn: ['Wasting with twitching (fasciculations) is a lower motor neuron sign, typical of anterior horn cell disease.', 'Low reflexes fit lower motor neuron loss; painless onset fits motor neuron disease.'],
  w: 'Motor neuron disease affects only motor neurons, so sensation stays normal.',
  st: ['Motor neurons are purely motor.', 'Sensory loss needs another level.', 'So sensory loss argues against motor neuron disease.'],
  p: 'Sensory loss is a red flag against motor neuron disease.', g: ['umn-lmn', 'motor-unit']},
 'case-117': {ti: 'Wasting hands and stiff legs with a twitching tongue', k: 'Localize',
  s: 'A 65-year-old man has had wasting hands and stiff legs for ten months. His speech has become slurred.',
  f: ['His tongue is thin and twitches, and his jaw jerk is brisk', 'His legs are stiff with upgoing toes; his wasted hands still have brisk reflexes', 'Sensation is normal; there is no level and no bladder problem'],
  q: 'Where is the problem?',
  o: ['Both upper and lower motor neurons (motor neuron disease)', 'Cervical spinal cord', 'Nerve roots and nerves', 'Neuromuscular junction'],
  r: ['Best fit. Upper and lower motor neuron signs together in the tongue, arms and legs with normal sensation is motor neuron disease (ALS).', 'A cervical cord lesion cannot cause tongue and jaw signs.', 'Root and nerve disease cannot cause stiffness or upgoing toes.', 'Junction disorders do not cause wasting, twitching or brisk reflexes.'],
  fn: ['A thin twitching tongue with a brisk jaw jerk mixes lower and upper motor neuron signs above the neck.', 'Brisk reflexes in wasted hands and stiff legs mix both types in the limbs.', 'Normal sensation and bladder exclude a cord lesion.'],
  w: 'Motor neuron disease damages both upper and lower motor neurons in several regions while sparing sensation.',
  st: ['Both types of motor sign are present.', 'They appear above and below the neck.', 'With normal sensation, that is motor neuron disease.'],
  p: 'A brisk jaw jerk helps separate motor neuron disease from a cervical cord lesion.', g: ['umn-lmn']},
 'case-118': {ti: 'A voice that fades', k: 'Localize',
  s: 'A 31-year-old man has double vision that comes and goes and a voice that becomes nasal during long conversations.',
  f: ['Looking up for a minute makes the lids droop more; a rest helps', 'Pupils, sensation, reflexes and strength at rest are normal', 'There is no fixed nerve pattern and no wasting'],
  q: 'Where is the problem?',
  o: ['Neuromuscular junction', 'Several cranial nerves', 'Muscle (myopathy)', 'Brainstem'],
  r: ['Best fit. Fluctuating, fatigable eye and voice weakness with normal pupils, sensation and reflexes points to the neuromuscular junction.', 'Cranial nerve lesions are fixed and often affect the pupil.', 'Myopathy is not usually fatigable in this way.', 'A brainstem lesion causes fixed deficits and other signs.'],
  fn: ['Lids that droop more with sustained upgaze show fatigability.', 'Normal pupils, sensation and reflexes exclude nerve and brainstem causes.', 'No fixed pattern or wasting argues against a structural lesion.'],
  w: 'At the junction, repeated use releases less effective transmitter, so weakness grows with effort and recovers with rest.',
  st: ['The weakness fluctuates.', 'Pupils and sensation are normal.', 'That is the neuromuscular junction.'],
  p: 'Fatigable ptosis with normal pupils points to myasthenia.', g: ['nmj-compare', 'motor-unit']},
 'case-119': {ti: 'Reflexes that come back', k: 'Predict',
  s: 'A 63-year-old ex-smoker has weak thighs, a dry mouth and low reflexes, with normal sensation.',
  f: ['Getting out of a chair is hard; his eyelids and eye movements are normal', 'The knee and ankle reflexes are barely present at rest'],
  q: 'Which result would support Lambert–Eaton?',
  o: ['The reflexes become stronger for a short time', 'The reflexes stay low', 'He gets weaker without any change in reflexes', 'Strength does not change after the squeeze'],
  r: ['Best fit. Brief strong effort temporarily increases transmitter release in Lambert–Eaton, so reflexes and strength briefly improve.', 'Persistently low reflexes do not support it.', 'Increasing weakness fits myasthenia or myopathy.', 'No change does not support it.'],
  fn: ['Weak hip and thigh muscles fit either a muscle disease or a junction problem.', 'Low reflexes at rest with a dry mouth point toward Lambert–Eaton rather than a myopathy.'],
  w: 'In Lambert–Eaton, calcium builds up in the nerve ending during brief maximal effort, temporarily improving transmission.',
  st: ['Recheck reflexes after brief effort.', 'Improvement is facilitation.', 'Facilitation supports Lambert–Eaton.'],
  p: 'Ask the person to squeeze hard, then recheck reflexes.', g: ['nmj-compare']},
 'case-120': {ti: 'Weak grip and buckling knees', k: 'Localize',
  s: 'A 69-year-old man has had a worsening grip and knees that buckle for three years, a little worse on the right.',
  f: ['The finger flexors and the quadriceps are particularly weak; sensation is normal', 'Muscle tests show a muscle (myopathic) pattern', 'There are no upgoing toes and no numbness in a nerve area'],
  q: 'Where is the problem?',
  o: ['Muscle, in a selective pattern (as in inclusion body myositis)', 'Several peripheral nerves', 'Several nerve roots', 'Neuromuscular junction'],
  r: ['Best fit. Selective finger flexor and quadriceps weakness, slightly uneven, with normal sensation and a myopathic pattern fits inclusion body myositis.', 'Multiple nerve lesions would cause numbness.', 'Root lesions would cause pain or numbness.', 'Junction disorders fluctuate and usually affect the eyes.'],
  fn: ['Finger flexor and quadriceps weakness with normal sensation is a distinctive pattern.', 'A myopathic pattern on testing confirms muscle.', 'No upper motor neuron or nerve signs exclude other levels.'],
  w: 'Some myopathies affect particular muscles rather than all proximal muscles. Inclusion body myositis characteristically weakens the finger flexors and quadriceps, often unevenly.',
  st: ['The weakness is selective and motor only.', 'Tests show a muscle pattern.', 'That fits a selective myopathy.'],
  p: 'Weak grip plus weak quadriceps in an older person suggests inclusion body myositis.', g: ['motor-unit', 'body-patterns']}
});
